interface FiltersState { program: string[]; subProgram: string[]; showCriticalOnly: boolean; }
const FilterDropdown: React.FC<{ label: string; options: string[]; selected: string[]; onToggle: (option: string) => void; }> = ({ label, options, selected, onToggle }) => {
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = React.useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) setIsOpen(false);
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const isActive = selected.length > 0;
    return (
        <div className="relative" ref={dropdownRef}>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={`flex items-center gap-2 px-3 py-1.5 text-sm font-semibold rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-900 ${
                    isActive ? 'bg-cyan-500 text-white hover:bg-cyan-600 focus:ring-cyan-400' : 'bg-slate-700 text-slate-200 hover:bg-slate-600 focus:ring-slate-500'
                }`}
            >
                {label}
                {isActive && <span className="bg-cyan-700 text-white text-xs font-bold rounded-full px-2">{selected.length}</span>}
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" /></svg>
            </button>
            {isOpen && (
                <div className="absolute top-full left-0 mt-2 w-64 bg-slate-800/90 backdrop-blur-sm border border-slate-700 rounded-lg shadow-2xl p-2 z-50">
                    <div className="max-h-60 overflow-y-auto pr-1">
                        {options.map(option => (
                            <label key={option} className="flex items-center gap-3 p-2 rounded-md hover:bg-slate-700 cursor-pointer">
                                <input type="checkbox" className="h-4 w-4 rounded bg-slate-600 border-slate-500 text-cyan-500 focus:ring-cyan-500" checked={selected.includes(option)} onChange={() => onToggle(option)} />
                                <span className="text-sm text-slate-200">{option}</span>
                            </label>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};
const PlannerFilters: React.FC<{
    masterTasks: MasterTask[];
    filters: FiltersState;
    onFilterChange: (filterType: keyof FiltersState, value: string | boolean) => void;
    onClearFilters: () => void;
}> = ({ masterTasks, filters, onFilterChange, onClearFilters }) => {
    const { t } = useLocalization();
    const uniquePrograms = useMemo(() => Array.from(new Set(masterTasks.map(mt => mt.program))), [masterTasks]);
    const uniqueSubPrograms = useMemo(() => {
        const relevantSubPrograms = masterTasks
            .filter(mt => filters.program.length === 0 || filters.program.includes(mt.program))
            .map(mt => mt.subProgram);
        return Array.from(new Set(relevantSubPrograms));
    }, [masterTasks, filters.program]);

    const hasActiveFilters = filters.program.length > 0 || filters.subProgram.length > 0 || filters.showCriticalOnly;

    return (
        <div className="px-2 pb-4 flex items-center gap-4 flex-wrap border-b border-slate-800 mb-4">
            <FilterDropdown label={t('admin.filters.program')} options={uniquePrograms} selected={filters.program} onToggle={(option) => onFilterChange('program', option)} />
            <FilterDropdown label={t('admin.filters.subProgram')} options={uniqueSubPrograms} selected={filters.subProgram} onToggle={(option) => onFilterChange('subProgram', option)} />
             <label className="flex items-center gap-3 p-2 rounded-lg bg-slate-700 hover:bg-slate-600 cursor-pointer transition-colors">
                <input type="checkbox" className="h-4 w-4 rounded bg-slate-600 border-slate-500 text-cyan-500 focus:ring-cyan-500" checked={filters.showCriticalOnly} onChange={(e) => onFilterChange('showCriticalOnly', e.target.checked)} />
                <span className="text-sm font-semibold text-slate-200">{t('admin.filters.criticalOnly')}</span>
            </label>
             {hasActiveFilters && (
                <button onClick={onClearFilters} className="text-sm font-semibold text-red-400 hover:text-red-300 transition-colors">{t('admin.filters.clear')}</button>
            )}
        </div>
    );
};


interface AdminPageProps {
  onUpdateTasks: (tasks: Task[]) => void;
  allTasks: Task[];
  allOperators: string[];
  masterTasks: MasterTask[];
  rankSettings: RankSettings;
}

const AdminPage: React.FC<AdminPageProps> = ({ onUpdateTasks, allTasks, allOperators, masterTasks, rankSettings }) => {
  const { t } = useLocalization();
  const [selectedTaskIds, setSelectedTaskIds] = useState<number[]>([]);
  const [stagedTasks, setStagedTasks] = useState<Task[]>([]);
  const [hoveredOperator, setHoveredOperator] = useState<string | null>(null);
  const [filters, setFilters] = useState<FiltersState>({ program: [], subProgram: [], showCriticalOnly: false });
  const [draggedTaskId, setDraggedTaskId] = useState<number | null>(null);
  const [dragOverTaskId, setDragOverTaskId] = useState<number | null>(null);

  const combinedTasks = useMemo(() => {
    const stagedTaskIds = new Set(stagedTasks.map(st => st.id));
    const baseTasks = allTasks.filter(t => !stagedTaskIds.has(t.id));
    return [...baseTasks, ...stagedTasks];
  }, [allTasks, stagedTasks]);

  const allTasksMap = useMemo(() => new Map(combinedTasks.map(t => [t.id, t])), [combinedTasks]);
  const masterTaskMap = useMemo(() => new Map(masterTasks.map(mt => [mt.name, mt])), [masterTasks]);

  const { readyToPlanTasks, waitingForDependenciesTasks, blockedTasks } = useMemo(() => {
    const unplanned = combinedTasks
      .filter(t => t.day === -1 && t.status !== TaskStatus.Completed && t.status !== TaskStatus.QualityOK)
      .sort((a,b) => a.displayOrder - b.displayOrder);

    const ready: Task[] = [];
    const waiting: Task[] = [];
    const blocked: Task[] = [];

    for (const task of unplanned) {
        const masterInfo = masterTaskMap.get(task.name);
        const programMatch = filters.program.length === 0 || (masterInfo && filters.program.includes(masterInfo.program));
        const subProgramMatch = filters.subProgram.length === 0 || (masterInfo && filters.subProgram.includes(masterInfo.subProgram));
        const criticalMatch = !filters.showCriticalOnly || !!task.isCritical;

        if (!programMatch || !subProgramMatch || !criticalMatch) continue;

        if (task.status === TaskStatus.OnHold) {
            blocked.push(task);
            continue;
        }

        const areDependenciesMet = (task.dependencies || []).every(depId => {
            const prereq = allTasksMap.get(depId);
            return prereq ? prereq.day !== -1 : false;
        });

        if (areDependenciesMet) {
            ready.push(task);
        } else {
            waiting.push(task);
        }
    }

    return { readyToPlanTasks: ready, waitingForDependenciesTasks: waiting, blockedTasks: blocked };
  }, [combinedTasks, allTasksMap, masterTaskMap, filters]);

  const operatorWorkloads = useMemo(() => {
    const workloads: { [key: string]: { scheduled: number, staged: number } } = {};
    allOperators.forEach(op => workloads[op] = { scheduled: 0, staged: 0 });

    allTasks.forEach(task => {
        if (task.day !== -1 && workloads[task.assignedTo] !== undefined) {
            workloads[task.assignedTo].scheduled += task.duration;
        }
    });
    stagedTasks.forEach(task => {
        if (task.day !== -1 && workloads[task.assignedTo] !== undefined) {
            workloads[task.assignedTo].staged += task.duration;
        }
    });
    return workloads;
  }, [allTasks, stagedTasks, allOperators]);

  const operatorTasks = useMemo(() => {
      const tasksByOp: Record<string, Task[]> = {};
      allOperators.forEach(op => tasksByOp[op] = []);
      combinedTasks.forEach(task => {
          if(task.assignedTo && tasksByOp[task.assignedTo] && task.day !== -1) {
              tasksByOp[task.assignedTo].push(task);
          }
      });
      return tasksByOp;
  }, [combinedTasks, allOperators]);


  const handleTaskSelect = (taskId: number) => {
    setSelectedTaskIds(prev => prev.includes(taskId) ? prev.filter(id => id !== taskId) : [...prev, taskId]);
  };

  const getEarliestStartHour = useCallback((taskToPlan: Task, operatorTasks: Task[]) => {
      let nextAvailableTotalHour = 0;
      if (operatorTasks.length > 0) {
          const sortedOpTasks = [...operatorTasks].sort((a, b) => ((a.day * WORK_DAY_HOURS) + a.startHour + a.duration) - ((b.day * WORK_DAY_HOURS) + b.startHour + b.duration));
          const lastTask = sortedOpTasks[sortedOpTasks.length - 1];
          nextAvailableTotalHour = (lastTask.day * WORK_DAY_HOURS) + lastTask.startHour + lastTask.duration;
      }

      const dependencyCompletionTotalHour = Math.max(0, ...(taskToPlan.dependencies || []).map(depId => {
          const prereqTask = allTasksMap.get(depId);
          if (!prereqTask || prereqTask.day === -1) return 0;
          return (prereqTask.day * WORK_DAY_HOURS) + prereqTask.startHour + prereqTask.duration;
      }));

      return Math.max(nextAvailableTotalHour, dependencyCompletionTotalHour);
  }, [allTasksMap]);

  const handlePlanTasks = (targetOperator: string) => {
      if (selectedTaskIds.length === 0) return;

      const newStagedTasks: Task[] = [];
      let currentOperatorTasks = [...(operatorTasks[targetOperator] || []), ...stagedTasks.filter(t => t.assignedTo === targetOperator)];

      for (const taskId of selectedTaskIds) {
          const taskToPlan = combinedTasks.find(t => t.id === taskId);
          if (!taskToPlan) continue;

          const earliestStartHour = getEarliestStartHour(taskToPlan, currentOperatorTasks);

          let newDay = Math.floor(earliestStartHour / WORK_DAY_HOURS);
          let newStartHour = earliestStartHour % WORK_DAY_HOURS;

          if (newStartHour + taskToPlan.duration > WORK_DAY_HOURS) {
            newDay += 1;
            newStartHour = 0;
          }

          const updatedTask: Task & { isStaged?: boolean } = {
              ...taskToPlan,
              day: newDay,
              startHour: newStartHour,
              assignedTo: targetOperator,
              status: TaskStatus.ToDo,
              notes: null,
              isStaged: true,
          };
          newStagedTasks.push(updatedTask);
          currentOperatorTasks.push(updatedTask);
      }
      setStagedTasks(prev => [...prev.filter(st => !selectedTaskIds.includes(st.id)), ...newStagedTasks]);
      setSelectedTaskIds([]);
  };

  const ghostPlacement = useMemo(() => {
      if (!hoveredOperator || selectedTaskIds.length === 0) return null;

      const selectedTasksToPlan = selectedTaskIds
          .map(id => combinedTasks.find(t => t.id === id))
          .filter((t): t is Task => !!t);

      if (selectedTasksToPlan.length === 0) return null;

      const totalDuration = selectedTasksToPlan.reduce((sum, t) => sum + t.duration, 0);

      const firstTask = selectedTasksToPlan[0];
      const operatorAllTasks = [...(operatorTasks[hoveredOperator] || []), ...stagedTasks.filter(t => t.assignedTo === hoveredOperator)];
      const earliestStartHour = getEarliestStartHour(firstTask, operatorAllTasks);

      return { startHour: earliestStartHour, duration: totalDuration };
  }, [hoveredOperator, selectedTaskIds, combinedTasks, operatorTasks, stagedTasks, getEarliestStartHour]);


  const operatorProficiency = useMemo(() => {
    if (selectedTaskIds.length !== 1) return new Map<string, Rank>();

    const taskName = combinedTasks.find(t => t.id === selectedTaskIds[0])?.name;
    if (!taskName) return new Map<string, Rank>();

    const proficiencyMap = new Map<string, Rank>();
    allOperators.forEach(op => {
        const count = allTasks.filter(t => t.assignedTo === op && t.name === taskName && (t.status === TaskStatus.Completed || t.status === TaskStatus.QualityOK)).length;
        proficiencyMap.set(op, getRank(count, rankSettings));
    });
    return proficiencyMap;
  }, [selectedTaskIds, allTasks, allOperators, rankSettings, combinedTasks]);

  const suggestedOperator = useMemo(() => {
    if (selectedTaskIds.length !== 1) return null;

    const maxWorkload = Math.max(...Object.values(operatorWorkloads).map((w: any) => w.scheduled), 1);
    let bestOperator: string | null = null;
    let maxScore = -Infinity;

    for (const operator of allOperators) {
        const proficiency = operatorProficiency.get(operator) || Rank.Unranked;
        const proficiencyScore = rankToScore[proficiency];
        const workload = operatorWorkloads[operator]?.scheduled || 0;

        const score = (proficiencyScore * 1.5) - (workload / maxWorkload);

        if (score > maxScore) {
            maxScore = score;
            bestOperator = operator;
        }
    }
    return bestOperator;
  }, [selectedTaskIds, allOperators, operatorWorkloads, operatorProficiency]);

  const handleCommit = () => {
      onUpdateTasks(combinedTasks);
      setStagedTasks([]);
  };

  const handleDiscard = () => {
      setStagedTasks([]);
  };

    const handleFilterChange = useCallback((filterType: keyof FiltersState, value: string | boolean) => { setFilters(prev => { const newFilters = { ...prev }; if (filterType === 'showCriticalOnly') { newFilters[filterType] = value as boolean; } else { const currentValues = prev[filterType as keyof Omit<FiltersState, 'showCriticalOnly'>]; if (currentValues.includes(value as never)) { newFilters[filterType as keyof Omit<FiltersState, 'showCriticalOnly'>] = currentValues.filter(v => v !== value) as any; } else { newFilters[filterType as keyof Omit<FiltersState, 'showCriticalOnly'>] = [...currentValues, value] as any; } } return newFilters; }); }, []);
    const handleClearFilters = useCallback(() => { setFilters({ program: [], subProgram: [], showCriticalOnly: false }); }, []);

    const handleDragStart = useCallback((e: React.DragEvent, taskId: number) => {
        e.dataTransfer.setData('text/plain', taskId.toString());
        e.dataTransfer.effectAllowed = 'move';
        setDraggedTaskId(taskId);
    }, []);

    const handleDragOver = useCallback((e: React.DragEvent, taskId: number) => {
        e.preventDefault();
        if (taskId !== dragOverTaskId) setDragOverTaskId(taskId);
    }, [dragOverTaskId]);

    const handleDragLeave = useCallback(() => { setDragOverTaskId(null); }, []);

    const handleDrop = useCallback((e: React.DragEvent, targetTaskId: number) => {
        e.preventDefault();
        if (draggedTaskId === null || draggedTaskId === targetTaskId) return;

        const list = readyToPlanTasks;
        const draggedIndex = list.findIndex(t => t.id === draggedTaskId);
        const targetIndex = list.findIndex(t => t.id === targetTaskId);
        if (draggedIndex === -1 || targetIndex === -1) return;

        const reorderedList = [...list];
        const [draggedItem] = reorderedList.splice(draggedIndex, 1);
        reorderedList.splice(targetIndex, 0, draggedItem);

        const newStagedChanges = reorderedList.map((task, index) => ({
            ...task,
            displayOrder: list[index].displayOrder, // Use original order to find a 'slot'
            isStaged: true,
        }));

        const finalStaged = newStagedChanges.map((task, index) => ({
            ...task,
            displayOrder: index + (allTasks.length - readyToPlanTasks.length) // Simplistic re-ordering, might need refinement
        }));

        setStagedTasks(prev => {
            const newIds = new Set(finalStaged.map(t => t.id));
            const oldStaged = prev.filter(t => !newIds.has(t.id));
            return [...oldStaged, ...finalStaged];
        });

        setDraggedTaskId(null);
        setDragOverTaskId(null);
    }, [draggedTaskId, readyToPlanTasks, allTasks.length]);

    const handleDragEnd = useCallback(() => {
        setDraggedTaskId(null);
        setDragOverTaskId(null);
    }, []);

  return (
    <div className="w-full h-full flex flex-col relative">
      <header className="flex-shrink-0 flex items-center justify-between pb-4 border-b border-slate-700 mb-6">
        <div>
            <h2 className="text-xl font-bold text-slate-100">{t('admin.title')}</h2>
            <p className="text-sm text-slate-400 mt-1">{t('admin.description')}</p>
        </div>
      </header>

      {stagedTasks.length > 0 && <CommitBar onCommit={handleCommit} onDiscard={handleDiscard} changeCount={stagedTasks.length} />}

      <div className="flex-grow grid grid-cols-12 gap-6 min-h-0">
        {/* Unplanned Tasks Sidebar */}
        <div className="bg-slate-900 p-4 rounded-2xl shadow-xl flex flex-col col-span-12 lg:col-span-4">
            <h2 className="text-lg font-semibold text-slate-200 mb-4 px-2 flex-shrink-0">{t('admin.unplannedTitle', readyToPlanTasks.length + waitingForDependenciesTasks.length + blockedTasks.length)}</h2>
            <PlannerFilters masterTasks={masterTasks} filters={filters} onFilterChange={handleFilterChange} onClearFilters={handleClearFilters} />
            <div className="overflow-y-auto space-y-6 pr-2 -mr-2 flex-grow" onDragOver={e => e.preventDefault()}>
                {/* Ready to Plan */}
                <div>
                    <h3 className="text-sm font-bold text-cyan-400 mb-2 px-2">{t('admin.readyToPlanTitle', readyToPlanTasks.length)}</h3>
                    <div className="space-y-3">
                        {readyToPlanTasks.length > 0 ? (
                            readyToPlanTasks.map(task => 
                                <UnplannedTaskCard
                                    key={task.id} 
                                    task={task} 
                                    isSelected={selectedTaskIds.includes(task.id)}
                                    onClick={() => handleTaskSelect(task.id)}
                                    dependencyCount={task.dependencies?.length || 0}
                                    statusColor={task.isCritical ? 'var(--tw-color-orange-500)' : 'var(--tw-color-cyan-500)'}
                                    draggable={true}
                                    isBeingDragged={draggedTaskId === task.id}
                                    isDragTarget={dragOverTaskId === task.id}
                                    onDragStart={(e) => handleDragStart(e, task.id)}
                                    onDragOver={(e) => handleDragOver(e, task.id)}
                                    onDrop={(e) => handleDrop(e, task.id)}
                                    onDragEnd={handleDragEnd}
                                    onDragLeave={handleDragLeave}
                                />
                            )
                        ) : (
                            <div className="text-center text-slate-500 p-4 text-sm">
                                <p>{t('admin.noReadyTasks')}</p>
                            </div>
                        )}
                    </div>
                </div>

                {/* Waiting on Dependencies */}
                {waitingForDependenciesTasks.length > 0 && (
                  <div>
                      <h3 className="text-sm font-bold text-purple-400 mb-2 px-2">{t('admin.waitingForDependenciesTitle', waitingForDependenciesTasks.length)}</h3>
                      <div className="space-y-3">
                          {waitingForDependenciesTasks.map(task => 
                              <UnplannedTaskCard 
                                  key={task.id} 
                                  task={task} 
                                  isSelected={false}
                                  onClick={() => {}}
                                  dependencyCount={task.dependencies?.length || 0}
                                  statusColor="var(--tw-color-purple-500)"
                                  draggable={false}
                                  isBeingDragged={false} isDragTarget={false}
                                  onDragStart={()=>{}} onDragEnd={()=>{}} onDragOver={()=>{}} onDrop={()=>{}} onDragLeave={()=>{}}
                              />
                          )}
                      </div>
                  </div>
                )}

                {/* Blocked */}
                {blockedTasks.length > 0 && (
                  <div>
                      <h3 className="text-sm font-bold text-amber-400 mb-2 px-2">{t('admin.blockedTitle', blockedTasks.length)}</h3>
                      <div className="space-y-3">
                          {blockedTasks.map(task => 
                              <UnplannedTaskCard 
                                  key={task.id} 
                                  task={task}
                                  isSelected={false}
                                  onClick={() => {}}
                                  dependencyCount={task.dependencies?.length || 0}
                                  statusColor="var(--tw-color-amber-500)"
                                  draggable={false}
                                  isBeingDragged={false} isDragTarget={false}
                                  onDragStart={()=>{}} onDragEnd={()=>{}} onDragOver={()=>{}} onDrop={()=>{}} onDragLeave={()=>{}}
                              />
                          )}
                      </div>
                  </div>
                )}
            </div>
        </div>

        {/* Operator Timelines */}
        <div className="bg-slate-900 rounded-2xl shadow-xl flex flex-col col-span-12 lg:col-span-8">
             <div className="p-4 flex-grow flex flex-col overflow-hidden">
                <h2 className="text-lg font-semibold text-slate-200 mb-4 px-2 flex-shrink-0">{t('admin.operatorsTitle')}</h2>
                <div className="overflow-y-auto space-y-3 pr-2 -mr-2 flex-grow">
                    {allOperators.map(operator => (
                        <OperatorTimeline
                            key={operator}
                            operator={operator}
                            workload={operatorWorkloads[operator].scheduled + operatorWorkloads[operator].staged}
                            tasks={operatorTasks[operator] || []}
                            isSuggested={suggestedOperator === operator}
                            hasSelection={selectedTaskIds.length > 0}
                            onHover={(isHovering) => setHoveredOperator(isHovering ? operator : null)}
                            onClick={() => handlePlanTasks(operator)}
                            ghostTask={hoveredOperator === operator ? ghostPlacement : undefined}
                            proficiency={operatorProficiency.get(operator)}
                        />
                    ))}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default AdminPage;

import React, { useState, useMemo, useRef, useEffect, useCallback } from 'react';
import { Task, TaskStatus, MasterTask, Rank, getRank, RankSettings } from '../types';
import { TASK_STATUS_COLORS, WORK_DAY_HOURS, rankToScore } from '../constants';
import { useLocalization } from '../contexts/LocalizationContext';

declare const XLSX: any;

interface OrderLogPageProps {
  allTasks: Task[];
  masterTasks: MasterTask[];
  onUpdateTasks: (tasks: Task[]) => void;
  onUpdateMasterTasks: (tasks: MasterTask[]) => void;
  allOperators: string[];
  rankSettings: RankSettings;
  columnVisibility: { [key: string]: boolean };
}

type SortKey = keyof Task | 'dueDate' | 'program';
interface SortConfig {
  key: SortKey;
  direction: 'ascending' | 'descending';
}

interface TaskToUpload {
    task: Task;
    changeType: 'New' | 'Update';
}

interface UnrecognizedTaskData {
    name: string;
    program: string;
    subProgram: string;
    shortName: string;
    defaultDuration: number;
    originalRow: any;
}


// Unrecognized Task Modal Component
const UnrecognizedTaskModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onConfirm: (newMasterTasks: MasterTask[]) => void;
    initialTasks: UnrecognizedTaskData[];
}> = ({ isOpen, onClose, onConfirm, initialTasks }) => {
    const { t } = useLocalization();
    const [tasks, setTasks] = useState<MasterTask[]>([]);
    const [errors, setErrors] = useState<Record<number, string>>({});

    useEffect(() => {
        if (isOpen) {
            setTasks(initialTasks.map(ut => ({
                name: ut.name,
                program: ut.program || '',
                subProgram: ut.subProgram || '',
                shortName: ut.shortName || '',
                defaultDuration: ut.defaultDuration || 1,
            })));
            setErrors({});
        }
    }, [isOpen, initialTasks]);

    const handleTaskChange = (index: number, field: keyof MasterTask, value: string | number) => {
        const newTasks = [...tasks];
        (newTasks[index] as any)[field] = value;
        setTasks(newTasks);
        if (errors[index]) {
            const newErrors = { ...errors };
            delete newErrors[index];
            setErrors(newErrors);
        }
    };

    const handleConfirmClick = () => {
        const newErrors: Record<number, string> = {};
        let isValid = true;
        tasks.forEach((task, index) => {
            if (!task.program || !task.subProgram || !task.shortName || !task.defaultDuration || Number(task.defaultDuration) < 1) {
                newErrors[index] = t('settingsModal.error.allFieldsRequired');
                isValid = false;
            }
        });

        if (isValid) {
            onConfirm(tasks);
        } else {
            setErrors(newErrors);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm" onClick={onClose}>
            <div className="bg-slate-800 rounded-2xl shadow-2xl p-6 flex flex-col w-full max-w-5xl max-h-[90vh] border border-slate-700" onClick={e => e.stopPropagation()}>
                <header className="flex-shrink-0 mb-4">
                    <h2 className="text-2xl font-bold text-slate-100">{t('orderlog.unrecognized.title')}</h2>
                    <p className="text-sm text-slate-400 mt-1">{t('orderlog.unrecognized.description')}</p>
                </header>
                <div className="flex-grow overflow-y-auto border border-slate-700 rounded-lg">
                    <table className="w-full text-sm">
                        <thead className="sticky top-0 bg-slate-800 shadow-sm">
                            <tr>
                                <th className="p-3 text-left text-xs font-semibold text-slate-400 uppercase tracking-wider w-1/4">{t('columns.task')}</th>
                                <th className="p-3 text-left text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('columns.program')}</th>
                                <th className="p-3 text-left text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('columns.subProgram')}</th>
                                <th className="p-3 text-left text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('columns.shortName')}</th>
                                <th className="p-3 text-left text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('columns.duration')}</th>
                            </tr>
                        </thead>
                        <tbody className="bg-slate-900/50">
                            {tasks.map((task, index) => (
                                <tr key={index} className="border-b border-slate-700/50">
                                    <td className="p-2 align-top"><span className="font-semibold text-white bg-slate-700 px-2 py-1 rounded-md inline-block">{task.name}</span></td>
                                    <td className="p-2 align-top"><input type="text" value={task.program} onChange={e => handleTaskChange(index, 'program', e.target.value)} className="w-full bg-slate-700 rounded-md p-2 text-white focus:ring-2 focus:ring-cyan-500 outline-none" /></td>
                                    <td className="p-2 align-top"><input type="text" value={task.subProgram} onChange={e => handleTaskChange(index, 'subProgram', e.target.value)} className="w-full bg-slate-700 rounded-md p-2 text-white focus:ring-2 focus:ring-cyan-500 outline-none" /></td>
                                    <td className="p-2 align-top"><input type="text" value={task.shortName} onChange={e => handleTaskChange(index, 'shortName', e.target.value)} className="w-full bg-slate-700 rounded-md p-2 text-white focus:ring-2 focus:ring-cyan-500 outline-none" /></td>
                                    <td className="p-2 align-top"><input type="number" min="1" value={task.defaultDuration} onChange={e => handleTaskChange(index, 'defaultDuration', Number(e.target.value))} className="w-24 bg-slate-700 rounded-md p-2 text-white focus:ring-2 focus:ring-cyan-500 outline-none" /></td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
                 {(Object.keys(errors).length > 0) && <p className="text-red-400 text-sm mt-3">{t('settingsModal.error.allFieldsRequired')}</p>}
                <footer className="flex justify-end items-center gap-4 mt-6 flex-shrink-0">
                    <button onClick={onClose} className="px-4 py-2 text-sm font-semibold rounded-lg transition-colors bg-slate-600 hover:bg-slate-500 text-white">{t('orderlog.unrecognized.cancel')}</button>
                    <button onClick={handleConfirmClick} className="px-4 py-2 text-sm font-semibold rounded-lg transition-colors bg-cyan-600 hover:bg-cyan-500 text-white">{t('orderlog.unrecognized.confirm')}</button>
                </footer>
            </div>
        </div>
    );
};


// Helper component for filter dropdowns
const FilterDropdown: React.FC<{
    label: string;
    options: readonly string[];
    selected: string[];
    onChange: (option: string) => void;
    onClear: () => void;
    getLabel: (value: string) => string;
}> = ({ label, options, selected, onChange, onClear, getLabel }) => {
    const { t } = useLocalization();
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const isActive = selected.length > 0;

    return (
        <div className="relative" ref={dropdownRef}>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={`flex items-center gap-2 px-3 py-1.5 text-sm font-semibold rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-800 ${
                    isActive ? 'bg-cyan-500 text-white hover:bg-cyan-600 focus:ring-cyan-400' : 'bg-slate-700 text-slate-200 hover:bg-slate-600 focus:ring-slate-500'
                }`}
            >
                {label}
                {isActive && <span className="bg-cyan-700 text-white text-xs font-bold rounded-full px-2">{selected.length}</span>}
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
                </svg>
            </button>
            {isOpen && (
                <div className="absolute top-full left-0 mt-2 w-64 bg-slate-900/90 backdrop-blur-sm border border-slate-700 rounded-lg shadow-2xl p-2 z-50">
                    <div className="max-h-60 overflow-y-auto pr-1">
                        {options.map(option => (
                            <label key={option} className="flex items-center gap-3 p-2 rounded-md hover:bg-slate-700/50 cursor-pointer">
                                <input
                                    type="checkbox"
                                    className="h-4 w-4 rounded bg-slate-600 border-slate-500 text-cyan-500 focus:ring-cyan-500 transition"
                                    checked={selected.includes(option)}
                                    onChange={() => onChange(option)}
                                />
                                <span className="text-sm text-slate-200">{getLabel(option)}</span>
                            </label>
                        ))}
                    </div>
                     {isActive && (
                        <div className="pt-2 mt-2 border-t border-slate-700">
                            <button
                                onClick={() => { onClear(); setIsOpen(false); }}
                                className="w-full text-center text-sm font-semibold text-red-400 hover:text-red-300 transition-colors py-1 rounded-md hover:bg-slate-700"
                            >
                                {t('actions.clearSelection')}
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

const SortableHeader: React.FC<{
    label: string;
    sortKey: SortKey;
    sortConfig: SortConfig | null;
    requestSort: (key: SortKey) => void;
    className?: string;
}> = ({ label, sortKey, sortConfig, requestSort, className }) => {
    const isSorted = sortConfig?.key === sortKey;
    const directionIcon = isSorted ? (sortConfig.direction === 'ascending' ? '▲' : '▼') : '';

    return (
        <th className={`p-3 text-left text-xs font-semibold text-slate-400 uppercase tracking-wider cursor-pointer hover:bg-slate-700/50 transition-colors ${className}`} onClick={() => requestSort(sortKey)}>
            <div className="flex items-center gap-2">
                {label}
                <span className="text-cyan-400">{directionIcon}</span>
            </div>
        </th>
    );
};


const OrderLogPage: React.FC<OrderLogPageProps> = ({ allTasks, masterTasks, onUpdateTasks, onUpdateMasterTasks, allOperators, rankSettings, columnVisibility }) => {
  const { t, getDaysOfWeek, getTaskStatusName } = useLocalization();
  const DAYS_OF_WEEK = getDaysOfWeek('long');
  const DAYS_OF_WEEK_SHORT = getDaysOfWeek('short');

  const [searchTerm, setSearchTerm] = useState('');
  const [sortConfig, setSortConfig] = useState<SortConfig | null>({ key: 'id', direction: 'ascending' });

  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [tasksToUpload, setTasksToUpload] = useState<TaskToUpload[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isUnrecognizedModalOpen, setIsUnrecognizedModalOpen] = useState(false);
  const [unrecognizedTasks, setUnrecognizedTasks] = useState<UnrecognizedTaskData[]>([]);
  const [stagedRecognizedRows, setStagedRecognizedRows] = useState<any[]>([]);

  const [offlineSuggestions, setOfflineSuggestions] = useState<{[key: number]: string}>({});

  const [contextFilters, setContextFilters] = useState<{
    programs: string[];
    statuses: TaskStatus[];
    assignedTo: string[];
    planningStatus: 'all' | 'planned' | 'unplanned';
  }>({
    programs: [],
    statuses: [],
    assignedTo: [],
    planningStatus: 'all',
  });

  const masterTaskMap = useMemo(() => new Map(masterTasks.map(mt => [mt.name, mt])), [masterTasks]);
  const uniquePrograms = useMemo(() => Array.from(new Set(masterTasks.map(mt => mt.program))), [masterTasks]);
  const allStatuses = useMemo(() => Object.values(TaskStatus), []);

  const handleFilterChange = useCallback((type: 'program' | 'status' | 'assignedTo', value: string) => {
    setContextFilters(prev => {
        const keyMap = { program: 'programs', status: 'statuses', assignedTo: 'assignedTo' };
        const key = keyMap[type];
        // FIX: The type of `currentValues` was being incorrectly widened to include non-array properties of the state.
        // By using `prev[key]`, we correctly infer that `currentValues` must be an array type.
        const currentValues = prev[key];
        const newValues = currentValues.includes(value as never)
            ? currentValues.filter(v => v !== value)
            : [...currentValues, value];
        return { ...prev, [key]: newValues as any };
    });
  }, []);

  const handlePlanningFilterChange = (status: 'all' | 'planned' | 'unplanned') => {
      setContextFilters(prev => ({ ...prev, planningStatus: status }));
  };

  const clearAllContextFilters = () => {
      setContextFilters({ programs: [], statuses: [], assignedTo: [], planningStatus: 'all' });
  };

  const hasActiveContextFilters = useMemo(() => {
      return contextFilters.programs.length > 0 || contextFilters.statuses.length > 0 || contextFilters.assignedTo.length > 0 || contextFilters.planningStatus !== 'all';
  }, [contextFilters]);

  const requestSort = (key: SortKey) => {
    let direction: 'ascending' | 'descending' = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  const getOperatorProficiency = useCallback((operator: string, taskName: string, tasks: Task[]): Rank => {
      const count = tasks.filter(t => t.assignedTo === operator && t.name === taskName && (t.status === TaskStatus.Completed || t.status === TaskStatus.QualityOK)).length;
      return getRank(count, rankSettings);
  }, [rankSettings]);

  const predictBestOperator = useCallback((taskToMatch: Task): string => {
    const operatorWorkloads = allOperators.reduce((acc, op) => {
        acc[op] = allTasks
            .filter(t => t.assignedTo === op && t.day !== -1)
            .reduce((sum, currentTask) => sum + currentTask.duration, 0);
        return acc;
    }, {} as {[key: string]: number});

    const maxWorkload = Math.max(...(Object.values(operatorWorkloads) as number[]), 1);

    let bestOperator = '';
    let maxScore = -Infinity;

    for (const operator of allOperators) {
        const proficiency = getOperatorProficiency(operator, taskToMatch.name, allTasks);
        const proficiencyScore = rankToScore[proficiency];

        const workload = operatorWorkloads[operator] || 0;
        const normalizedWorkload = workload / maxWorkload;

        const score = (proficiencyScore * 100) - normalizedWorkload;

        if (score > maxScore) {
            maxScore = score;
            bestOperator = operator;
        }
    }

    return bestOperator || allOperators[0];
  }, [allTasks, allOperators, getOperatorProficiency]);

  const handleSuggestOperator = (taskToMatch: Task) => {
      const prediction = predictBestOperator(taskToMatch);
      setOfflineSuggestions(prev => ({ ...prev, [taskToMatch.id]: prediction }));
  };


  const handleAssignTask = (taskToPlan: Task, targetOperator: string) => {
      const operatorTasks = allTasks
          .filter(t => t.assignedTo === targetOperator && t.day !== -1)
          .sort((a, b) => ((a.day * WORK_DAY_HOURS) + a.startHour) - ((b.day * WORK_DAY_HOURS) + b.startHour));

      let nextAvailableTotalHour = 0;
      if (operatorTasks.length > 0) {
          const lastTask = operatorTasks[operatorTasks.length - 1];
          nextAvailableTotalHour = (lastTask.day * WORK_DAY_HOURS) + lastTask.startHour + lastTask.duration;
      }

      let newDay = Math.floor(nextAvailableTotalHour / WORK_DAY_HOURS);
      let newStartHour = nextAvailableTotalHour % WORK_DAY_HOURS;

      if (newStartHour + taskToPlan.duration > WORK_DAY_HOURS) {
        newDay += 1;
        newStartHour = 0;
      }

      if (newStartHour === WORK_DAY_HOURS) {
          newDay += 1;
          newStartHour = 0;
      }

      const updatedTask = {
          ...taskToPlan,
          day: newDay,
          startHour: newStartHour,
          assignedTo: targetOperator,
          status: TaskStatus.ToDo,
          notes: null,
      };

      const newTaskList = allTasks.map(t => t.id === updatedTask.id ? updatedTask : t);
      onUpdateTasks(newTaskList);
  };

  const sortedAndFilteredTasks = useMemo(() => {
    let sortableItems = [...allTasks];

    // Search filter
    const lowercasedFilter = searchTerm.toLowerCase();
    if (lowercasedFilter) {
      sortableItems = sortableItems.filter(item => {
          const masterInfo = masterTaskMap.get(item.name);
          return (
            item.name.toLowerCase().includes(lowercasedFilter) ||
            item.orderId.toLowerCase().includes(lowercasedFilter) ||
            masterInfo?.program.toLowerCase().includes(lowercasedFilter) ||
            masterInfo?.subProgram.toLowerCase().includes(lowercasedFilter)
          )
      });
    }

    // Contextual filters
    if (contextFilters.programs.length > 0) {
        sortableItems = sortableItems.filter(item => {
            const program = masterTaskMap.get(item.name)?.program;
            return program ? contextFilters.programs.includes(program) : false;
        });
    }

    if (contextFilters.statuses.length > 0) {
        sortableItems = sortableItems.filter(item => contextFilters.statuses.includes(item.status));
    }

    if (contextFilters.assignedTo.length > 0) {
        sortableItems = sortableItems.filter(item => contextFilters.assignedTo.includes(item.assignedTo));
    }

    if (contextFilters.planningStatus !== 'all') {
        sortableItems = sortableItems.filter(item => {
            const isUnplanned = item.day === -1;
            if (contextFilters.planningStatus === 'planned') return !isUnplanned;
            if (contextFilters.planningStatus === 'unplanned') return isUnplanned;
            return true;
        });
    }

    // Sorting
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        let aValue, bValue;
        if (sortConfig.key === 'dueDate') {
            aValue = a.dueDay * 24 + a.dueHour;
            bValue = b.dueDay * 24 + b.dueHour;
        } else if (sortConfig.key === 'program') {
            aValue = masterTaskMap.get(a.name)?.program || '';
            bValue = masterTaskMap.get(b.name)?.program || '';
        } else {
            aValue = a[sortConfig.key as keyof Task];
            bValue = b[sortConfig.key as keyof Task];
        }
        if (aValue < bValue) return sortConfig.direction === 'ascending' ? -1 : 1;
        if (aValue > bValue) return sortConfig.direction === 'ascending' ? 1 : -1;
        return 0;
      });
    }
    return sortableItems;
  }, [allTasks, searchTerm, sortConfig, masterTaskMap, contextFilters]);

  const formatTasksForExport = (tasks: Task[]) => {
    return tasks.map(task => {
        const masterTask = masterTaskMap.get(task.name);
        return {
            'ID': task.id,
            'Program': masterTask?.program || t('na'),
            'Sub-Program': masterTask?.subProgram || t('na'),
            'Order ID': task.orderId,
            'Name': task.name,
            'Short Name': task.shortName,
            'Status': getTaskStatusName(task.status),
            'Assigned To': task.day === -1 ? t('unplanned') : task.assignedTo,
            'Progress (%)': task.progress,
            'Description': task.description.replace(/\n/g, ' '),
            'Planned Day': task.day === -1 ? t('unplanned') : DAYS_OF_WEEK[task.day],
            'Start Hour': task.day === -1 ? t('na') : task.startHour,
            'Duration (hrs)': task.duration,
            'Due Day': DAYS_OF_WEEK[task.dueDay],
            'Due Hour': task.dueHour,
        }
    });
  };

  const handleFileUploadClick = () => {
    fileInputRef.current?.click();
  };

  const processTasks = (importedTasks: Partial<Task>[]) => {
    const existingTaskIds = new Set(allTasks.map(t => t.id));
    const maxExistingId = allTasks.length > 0 ? Math.max(...allTasks.map(t => t.id)) : 0;
    let newIdCounter = 1;

    const processedTasks: TaskToUpload[] = importedTasks.map((importedTask, index) => {
        const baseTask: Partial<Task> = {
            id: 0, orderId: '', name: '', shortName: '',
            day: -1, startHour: -1, duration: 1, assignedTo: '', status: TaskStatus.ToDo,
            description: '', dueDay: 0, dueHour: 0, progress: 0, notes: null,
            displayOrder: 0,
        };

        const isUpdate = importedTask.id !== undefined && existingTaskIds.has(importedTask.id);

        let finalTask: Task;
        if (isUpdate) {
            const originalTask = allTasks.find(t => t.id === importedTask.id)!;
            finalTask = { ...originalTask, ...importedTask } as Task;
        } else {
            const newId = maxExistingId + newIdCounter++;
            finalTask = { ...baseTask, ...importedTask, id: newId } as Task;
            if (importedTask.displayOrder === undefined) {
                finalTask.displayOrder = allTasks.length + index;
            }
        }

        return {
            task: finalTask,
            changeType: isUpdate ? 'Update' : 'New',
        };
    });
    setTasksToUpload(processedTasks);
    setUploadError(null);
    setIsUploadModalOpen(true);
  };

  const getValueFromRow = (row: any, keys: string[]): any => {
    const rowKeys = Object.keys(row);
    for (const alias of keys) {
        const matchingRowKey = rowKeys.find(rk => rk.trim().toLowerCase() === alias.toLowerCase());
        if (matchingRowKey) {
          const value = row[matchingRowKey];
          if (value !== undefined && value !== null && String(value).trim() !== '') {
              return value;
          }
        }
    }
    return undefined;
  };

  const processTasksFromData = (rows: any[], currentMasterTasks: MasterTask[]) => {
    const currentMasterTaskMap = new Map(currentMasterTasks.map(mt => [mt.name, mt]));
    const dayNameToIndexMap = new Map<string, number>();
    getDaysOfWeek('long').forEach((day, i) => dayNameToIndexMap.set(day.toLowerCase(), i));
    ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'].forEach((day, i) => dayNameToIndexMap.set(day.toLowerCase(), i));
    ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'].forEach((day, i) => dayNameToIndexMap.set(day.toLowerCase(), i));
    const statusNameToEnum: { [key: string]: TaskStatus } = {};
    allStatuses.forEach(s => {
        const statusName = getTaskStatusName(s);
        if (statusName) statusNameToEnum[statusName.toLowerCase()] = s;
        statusNameToEnum[s.toLowerCase()] = s;
    });

    const tasksFromExcel = rows.map((row): Partial<Task> | null => {
        const name = getValueFromRow(row, ['Name', 'Task Name', 'Task', 'Nom', 'Nom de la Tâche', 'Tâche']);
        const orderId = getValueFromRow(row, ['Order ID', 'Order #', 'Order No.', 'Order Number', 'Order', 'ID Commande', 'N° Commande', 'No Commande', 'Commande']);

        if (!name || !orderId) return null;

        const masterInfo = currentMasterTaskMap.get(String(name));
        let duration;
        const durationHrs = getValueFromRow(row, ['Duration (hrs)', 'Duration', 'Durée (h)', 'Durée']);
        if (durationHrs !== undefined) { duration = Number(durationHrs); }
        else { const durationDays = getValueFromRow(row, ['Duration (days)', 'Durée (j)']); if (durationDays !== undefined) duration = Number(durationDays) * WORK_DAY_HOURS; }
        if(duration === undefined || isNaN(duration) || duration <= 0) duration = masterInfo?.defaultDuration || 1;

        const id = getValueFromRow(row, ['ID']);
        const plannedDayStr = (getValueFromRow(row, ['Planned Day', 'Jour Planifié']) || 'unplanned').toString().toLowerCase();
        const dueDayStr = (getValueFromRow(row, ['Due Day', 'Jour Limite', 'Date Limite', "Date d'échéance"]) || '').toString().toLowerCase();
        const statusStr = (getValueFromRow(row, ['Status', 'Statut']) || '').toString().toLowerCase();
        const status = statusNameToEnum[statusStr] || TaskStatus.ToDo;
        const assignedToStr = getValueFromRow(row, ['Assigned To', 'Assigné à', 'Operateur', 'Operator']);
        let assignedTo = allOperators.includes(assignedToStr) ? assignedToStr : '';
        const task: Partial<Task> = {
            id: id !== undefined ? Number(id) : undefined,
            orderId: String(orderId), name: String(name),
            shortName: String(getValueFromRow(row, ['Short Name', 'Nom Court']) || masterInfo?.shortName || ''),
            status, assignedTo,
            progress: Number(getValueFromRow(row, ['Progress (%)', 'Progression (%)', 'Progrès (%)']) || 0),
            description: String(getValueFromRow(row, ['Description']) || masterInfo?.name || t('na')),
            day: plannedDayStr === 'unplanned' ? -1 : (dayNameToIndexMap.get(plannedDayStr) ?? -1),
            startHour: plannedDayStr === 'unplanned' ? -1 : Number(getValueFromRow(row, ['Start Hour', 'Heure de Début']) === 'N/A' ? -1 : getValueFromRow(row, ['Start Hour', 'Heure de Début']) || -1),
            duration, dueDay: dayNameToIndexMap.get(dueDayStr) ?? 0,
            dueHour: Number(getValueFromRow(row, ['Due Hour', 'Heure Limite']) || 0),
        };
        if (task.id !== undefined && isNaN(task.id)) { console.warn('Invalid ID found in row, ignoring ID field:', JSON.stringify(row)); delete task.id; }
        return task;
    }).filter((task): task is Partial<Task> => task !== null);

    if (tasksFromExcel.length === 0 && rows.length > 0) {
        const foundHeaders = Object.keys(rows[0]).join(', ');
        const errorMessage = `${t('orderlog.upload.missingFields')}\n${t('orderlog.upload.foundHeaders')}: ${foundHeaders}`;
        throw new Error(errorMessage);
    }
    processTasks(tasksFromExcel);
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();

    const handleError = (error: unknown) => {
        console.error("File upload error:", error);
        const message = error instanceof Error ? error.message : t('orderlog.upload.unknownError');
        setUploadError(message);
        setTasksToUpload([]);
        setIsUploadModalOpen(true);
    };

    const analyzeData = (jsonData: any[]) => {
        try {
            const currentMasterTaskNames = new Set(masterTasks.map(mt => mt.name.toLowerCase()));
            const recognizedRows: any[] = [];
            const unrecognizedData: UnrecognizedTaskData[] = [];

            jsonData.forEach(row => {
                const name = getValueFromRow(row, ['Name', 'Task Name', 'Task', 'Nom', 'Nom de la Tâche', 'Tâche']);
                if (name && String(name).trim()) {
                    if (currentMasterTaskNames.has(String(name).toLowerCase())) {
                        recognizedRows.push(row);
                    } else {
                        unrecognizedData.push({
                            name: String(name),
                            program: getValueFromRow(row, ['Program', 'Programme']) || '',
                            subProgram: getValueFromRow(row, ['Sub-Program', 'Sub Program', 'Sous-Programme']) || '',
                            shortName: getValueFromRow(row, ['Short Name', 'Shortname', 'Nom Court']) || '',
                            defaultDuration: Number(getValueFromRow(row, ['Default Duration (hrs)', 'Default Duration', 'Duration', 'Durée par Défaut (h)', 'Durée par Défaut', 'Durée'])) || 1,
                            originalRow: row,
                        });
                    }
                }
            });

            if (unrecognizedData.length > 0) {
                setStagedRecognizedRows(recognizedRows);
                setUnrecognizedTasks(unrecognizedData);
                setIsUnrecognizedModalOpen(true);
            } else if (recognizedRows.length > 0) {
                processTasksFromData(recognizedRows, masterTasks);
            } else {
                throw new Error(t('orderlog.upload.missingFields'));
            }
        } catch(error) { handleError(error) }
    };

    if (file.name.endsWith('.json')) {
        reader.onload = (e) => {
            try {
                const text = e.target?.result;
                if (typeof text !== 'string') throw new Error(t('orderlog.upload.notReadable'));
                const data = JSON.parse(text);
                if (!Array.isArray(data)) throw new Error(t('orderlog.upload.invalidJsonFormat'));
                analyzeData(data);
            } catch (error) { handleError(error); }
        };
        reader.readAsText(file);
    } else if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                if (!data) throw new Error(t('orderlog.upload.emptyFile'));
                const workbook = XLSX.read(data, { type: 'array' });
                const worksheet = workbook.Sheets[workbook.SheetNames[0]];
                const jsonData: any[] = XLSX.utils.sheet_to_json(worksheet);
                analyzeData(jsonData);
            } catch (error) { handleError(error); }
        };
        reader.readAsArrayBuffer(file);
    } else {
        handleError(new Error(t('orderlog.upload.unsupportedType')));
    }

    event.target.value = '';
  };

  const handleConfirmAddMasterTasks = (newlyDefinedMasterTasks: MasterTask[]) => {
      onUpdateMasterTasks([...masterTasks, ...newlyDefinedMasterTasks]);

      const allRowsToProcess = [
          ...stagedRecognizedRows,
          ...unrecognizedTasks.map(ut => ut.originalRow)
      ];

      const updatedMasterTasks = [...masterTasks, ...newlyDefinedMasterTasks];
      processTasksFromData(allRowsToProcess, updatedMasterTasks);

      setIsUnrecognizedModalOpen(false);
      setStagedRecognizedRows([]);
      setUnrecognizedTasks([]);
  };

  const handleConfirmUpload = () => {
    const taskMap = new Map(allTasks.map(t => [t.id, t]));
    tasksToUpload.forEach(({ task }) => {
        taskMap.set(task.id, task);
    });
    const mergedTasks = Array.from(taskMap.values());
    onUpdateTasks(mergedTasks);
    closeModal();
  };

  const closeModal = () => {
      setIsUploadModalOpen(false);
      setUploadError(null);
      setTasksToUpload([]);
  };

  const uploadSummary = useMemo(() => {
    if (uploadError) return null;
    const newCount = tasksToUpload.filter(t => t.changeType === 'New').length;
    const updatedCount = tasksToUpload.filter(t => t.changeType === 'Update').length;
    return { newCount, updatedCount };
  }, [tasksToUpload, uploadError]);

  const handleExportCSVClick = () => {
    if (sortedAndFilteredTasks.length === 0) {
        alert(t('orderlog.export.noData'));
        return;
    }

    const dataToExport = formatTasksForExport(sortedAndFilteredTasks);
    if (dataToExport.length === 0) return;

    const headers = Object.keys(dataToExport[0]);
    const escapeCsvCell = (cellData: any): string => {
        const stringData = String(cellData ?? '');
        if (/[",\n]/.test(stringData)) {
            return `"${stringData.replace(/"/g, '""')}"`;
        }
        return stringData;
    };

    const csvContent = [
        headers.join(','),
        ...dataToExport.map(row => headers.map(header => escapeCsvCell(row[header as keyof typeof row])).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    const timestamp = new Date().toISOString().split('T')[0];
    link.setAttribute("download", `order_database_export_${timestamp}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleExportXLSXClick = () => {
    if (sortedAndFilteredTasks.length === 0) {
        alert(t('orderlog.export.noData'));
        return;
    }
    const dataToExport = formatTasksForExport(sortedAndFilteredTasks);
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "OrderData");

    const timestamp = new Date().toISOString().split('T')[0];
    XLSX.writeFile(workbook, `order_database_export_${timestamp}.xlsx`);
  };

  return (
    <div className="w-full h-full bg-slate-800 rounded-2xl shadow-2xl p-6 flex flex-col">
