                                        </svg>
                                        {t('actions.suggestMatch')}
                                    </button>
                                )
                            ) : (
                                <span className="text-slate-500 text-xs italic">{t('na')}</span>
                            )}
                        </td>}
                    </tr>
                );
            })}
          </tbody>
        </table>
        {sortedAndFilteredTasks.length === 0 && (
            <div className="text-center py-16 text-slate-500">
                <p>{t('orderlog.noOrders')}</p>
