const App: React.FC = () => {
  const { t } = useLocalization();
  const { addToast } = useToast();

  const [isLoading, setIsLoading] = useState(true);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [operators, setOperators] = useState<string[]>([]);
  const [proficiencyOverrides, setProficiencyOverrides] = useState<ProficiencyOverrides>({});
  const [masterTasks, setMasterTasks] = useState<MasterTask[]>([]);
  const [rankSettings, setRankSettings] = useState<RankSettings>({ master: 0, senior: 0, junior: 0, trainee: 0 });

  const [currentView, setCurrentView] = useState<ViewType>('gantt');
  const [isModalSidebarOpen, setIsModalSidebarOpen] = useState(false);
  const [isDashboardOpen, setIsDashboardOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedOperator, setSelectedOperator] = useState<string | null>(null);

  const [ganttColumnVisibility, setGanttColumnVisibility] = useState({ orderId: true, quality: false, realisation: false, assignedTo: true, status: true, progress: true, dueBy: true, duration: true });
  const [orderLogColumnVisibility, setOrderLogColumnVisibility] = useState({ program: true, orderId: true, task: true, status: true, assignedTo: true, dueBy: true, bestMatch: true });
  const [taskDatabaseColumnVisibility, setTaskDatabaseColumnVisibility] = useState({ program: true, subProgram: true, task: true, shortName: true, defaultDuration: true, actions: true });

  const [isColumnMenuOpen, setIsColumnMenuOpen] = useState(false);
  const [isGanttInteracting, setIsGanttInteracting] = useState(false);

  useEffect(() => {
    const initializeApp = async () => {
        try {
            await db.initDB();
            const allData = await db.getAllData();
            setTasks(allData.tasks);
            setOperators(allData.operators);
            setMasterTasks(allData.masterTasks);
            setProficiencyOverrides(allData.proficiencyOverrides);
            setRankSettings(allData.rankSettings);
            addToast("Database loaded successfully.", "success");
        } catch (error) {
            console.error("Failed to initialize database:", error);
            addToast("Error initializing database.", "error");
        } finally {
            setIsLoading(false);
        }
    };
    initializeApp();
  }, [addToast]);

  const handleSetTasks = useCallback(async (newTasks: Task[]) => {
    await db.replaceTasks(newTasks);
    const refreshedTasks = await db.getTasks();
    setTasks(refreshedTasks);
    setSelectedTask(null);
    setSelectedOperator(null);
  }, []);

  const handleSetOperators = useCallback(async (newOperators: string[]) => {
    await db.replaceOperators(newOperators);
    const refreshedOperators = await db.getOperators();
    setOperators(refreshedOperators);
    setSelectedOperator(null);
    setFilters(f => ({ ...f, operator: [] }));
  }, []);

  const handleTaskUpdate = useCallback(async (updatedTask: Task) => {
    await db.updateTask(updatedTask);
    const refreshedTasks = await db.getTasks();
    setTasks(refreshedTasks);
    if (selectedTask?.id === updatedTask.id) {
      setSelectedTask(updatedTask);
    }
  }, [selectedTask?.id]);

  const handleSetProficiencyOverrides = useCallback(async (newOverrides: ProficiencyOverrides) => {
    await db.replaceProficiencyOverrides(newOverrides);
    const refreshedOverrides = await db.getProficiencyOverrides();
    setProficiencyOverrides(refreshedOverrides);
  }, []);

  const handleSetMasterTasks = useCallback(async (newMasterTasks: MasterTask[]) => {
    await db.replaceMasterTasks(newMasterTasks);
    const refreshedMasterTasks = await db.getMasterTasks();
    setMasterTasks(refreshedMasterTasks);
  }, []);

  const handleSetRankSettings = useCallback(async (newRankSettings: RankSettings) => {
    await db.updateRankSettings(newRankSettings);
    const refreshedRankSettings = await db.getRankSettings();
    setRankSettings(refreshedRankSettings);
  }, []);

  const [filters, setFilters] = useState<Filters>({ status: [], operator: [], showOverdueOnly: false, program: [], subProgram: [], showCriticalOnly: false });

  const columnVisibilityConfig = useMemo(() => ({
      gantt: { state: ganttColumnVisibility, setter: setGanttColumnVisibility, config: ganttColumnsConfig },
      orderlog: { state: orderLogColumnVisibility, setter: setOrderLogColumnVisibility, config: orderLogColumnsConfig },
      taskdatabase: { state: taskDatabaseColumnVisibility, setter: setTaskDatabaseColumnVisibility, config: taskDatabaseColumnsConfig }
  }), [ganttColumnVisibility, orderLogColumnVisibility, taskDatabaseColumnVisibility]);

  const handleColumnToggle = useCallback((id: string) => {
      const viewConfig = columnVisibilityConfig[currentView as keyof typeof columnVisibilityConfig];
      if (viewConfig) {
          viewConfig.setter((prev: any) => ({ ...prev, [id]: !prev[id] }));
      }
  }, [currentView, columnVisibilityConfig]);

  const handleGanttTaskSelect = useCallback((task: Task) => {
    setSelectedTask(task);
    setSelectedOperator(null);
    setIsModalSidebarOpen(true);
    setIsDashboardOpen(false);
  }, []);

  const handleOperatorTaskSelect = useCallback((task: Task) => {
    setSelectedTask(task);
    setIsModalSidebarOpen(true);
  }, []);

  const handleOperatorSelect = useCallback((operatorName: string) => {
    setSelectedOperator(operatorName);
    setSelectedTask(null);
    setIsModalSidebarOpen(true);
    setIsDashboardOpen(false);
  }, []);

  const handleBackToOperator = useCallback(() => { setSelectedTask(null); }, []);

  const handleSidebarClose = () => {
    setIsModalSidebarOpen(false);
    setSelectedTask(null);
    setSelectedOperator(null);
  };

  const handleNavigate = (view: ViewType) => {
      setCurrentView(view);
      handleSidebarClose();
      setIsDashboardOpen(false);
      setIsColumnMenuOpen(false);
  };

  const handleToggleDashboard = () => {
    if (isGanttInteracting) return;

    setIsDashboardOpen(prev => {
        const turningOn = !prev;
        if (turningOn) {
            if (currentView !== 'gantt') {
                setCurrentView('gantt');
            }
            setIsModalSidebarOpen(false);
            setSelectedTask(null);
            setSelectedOperator(null);
        }
        return turningOn;
    });
  };

  const handleFilterChange = useCallback((filterType: keyof Filters, value: string | boolean) => { setFilters(prev => { const newFilters = { ...prev }; if (filterType === 'showOverdueOnly' || filterType === 'showCriticalOnly') { newFilters[filterType] = value as boolean; } else { const currentValues = prev[filterType as keyof Omit<Filters, 'showOverdueOnly' | 'showCriticalOnly'>]; if (currentValues.includes(value as never)) { newFilters[filterType as keyof Omit<Filters, 'showOverdueOnly' | 'showCriticalOnly'>] = currentValues.filter(v => v !== value) as any; } else { newFilters[filterType as keyof Omit<Filters, 'showOverdueOnly' | 'showCriticalOnly'>] = [...currentValues, value] as any; } } return newFilters; }); }, []);
  const handleClearFilters = useCallback(() => { setFilters({ status: [], operator: [], showOverdueOnly: false, program: [], subProgram: [], showCriticalOnly: false }); }, []);
  const masterTaskMap = useMemo(() => new Map(masterTasks.map(mt => [mt.name, mt])), [masterTasks]);

  const visibleTasks = useMemo(() => { return tasks.filter(task => { if (task.day === -1) return false; const statusMatch = filters.status.length === 0 || filters.status.includes(task.status); const operatorMatch = filters.operator.length === 0 || filters.operator.includes(task.assignedTo); const overdueMatch = !filters.showOverdueOnly || (isTaskOverdue(task) && task.status !== TaskStatus.Completed); const masterInfo = masterTaskMap.get(task.name); const programMatch = filters.program.length === 0 || (masterInfo && filters.program.includes(masterInfo.program)); const subProgramMatch = filters.subProgram.length === 0 || (masterInfo && filters.subProgram.includes(masterInfo.subProgram)); const criticalMatch = !filters.showCriticalOnly || !!task.isCritical; return statusMatch && operatorMatch && overdueMatch && programMatch && subProgramMatch && criticalMatch; }); }, [tasks, filters, masterTaskMap]);
  useEffect(() => { if (selectedTask && !visibleTasks.some(t => t.id === selectedTask.id)) { setSelectedTask(null); } }, [visibleTasks, selectedTask]);
  const operatorTasks = useMemo(() => { if (!selectedOperator) return []; return tasks.filter(t => t.assignedTo === selectedOperator && t.day !== -1).sort((a, b) => (a.day * WORK_DAY_HOURS + a.startHour) - (b.day * WORK_DAY_HOURS + b.startHour)); }, [tasks, selectedOperator]);

  const handleTaskReorder = useCallback(async (draggedTaskId: number, targetTaskId: number) => {
    const currentTasks = await db.getTasks(); // Fetch fresh tasks to avoid race conditions
    const draggedTaskIndex = currentTasks.findIndex(t => t.id === draggedTaskId);
    const targetTaskIndex = currentTasks.findIndex(t => t.id === targetTaskId);
    if (draggedTaskIndex === -1 || targetTaskIndex === -1) return;

    const newTasks = [...currentTasks];
    const [draggedItem] = newTasks.splice(draggedTaskIndex, 1);
    newTasks.splice(targetTaskIndex, 0, draggedItem);

    const reorderedTasks = newTasks.map((task, index) => ({ ...task, displayOrder: index }));

    await handleSetTasks(reorderedTasks);
  }, [handleSetTasks]);

  const pageTitles: { [key: string]: string } = useMemo(() => ({ 
    gantt: t('pageTitle.gantt'), 
    admin: t('pageTitle.admin'), 
    aiplanner: t('pageTitle.aiPlanner'),
    aiagent: t('pageTitle.aiAgent'),
    simulator: t('pageTitle.simulator'),
    orderlog: t('pageTitle.orderlog'), 
    userlog: t('pageTitle.userlog'), 
    taskdatabase: t('pageTitle.taskdatabase'), 
  }), [t]);

  if (isLoading) {
    return (
        <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-white gap-4">
            <AeroIcon />
            <h1 className="text-xl font-bold">Initializing Database...</h1>
            <p className="text-slate-400">Please wait, loading persisted data.</p>
        </div>
    );
  }

  const renderCurrentView = () => {
    switch (currentView) {
      case 'admin': return ( <AdminPage onUpdateTasks={handleSetTasks} allTasks={tasks} allOperators={operators} masterTasks={masterTasks} rankSettings={rankSettings} /> );
      case 'aiplanner': return ( <AIPlannerPage onUpdateTasks={handleSetTasks} allTasks={tasks} allOperators={operators} masterTasks={masterTasks} rankSettings={rankSettings} /> );
      case 'aiagent': return ( <AIAgentPage allTasks={tasks} masterTasks={masterTasks} onUpdateTasks={handleSetTasks} onUpdateMasterTasks={handleSetMasterTasks} /> );
      case 'simulator': return ( <SimulatorPage onUpdateTasks={handleSetTasks} allTasks={tasks} allOperators={operators} masterTasks={masterTasks} /> );
      case 'orderlog': return ( <OrderLogPage allTasks={tasks} masterTasks={masterTasks} onUpdateTasks={handleSetTasks} onUpdateMasterTasks={handleSetMasterTasks} allOperators={operators} rankSettings={rankSettings} columnVisibility={orderLogColumnVisibility}/> );
      case 'userlog': return ( <UserLogPage allOperators={operators} allTasks={tasks} masterTasks={masterTasks} onUpdateMasterTasks={handleSetMasterTasks} proficiencyOverrides={proficiencyOverrides} onUpdateOverrides={handleSetProficiencyOverrides} rankSettings={rankSettings} onUpdateRankSettings={handleSetRankSettings} /> );
      case 'taskdatabase': return ( <TaskDatabasePage allTasks={tasks} masterTasks={masterTasks} onUpdateMasterTasks={handleSetMasterTasks} columnVisibility={taskDatabaseColumnVisibility} /> );
      case 'gantt':
      default: return ( <GanttChart tasks={visibleTasks} allTasks={tasks} onTaskSelect={handleGanttTaskSelect} selectedTaskId={selectedTask?.id} onTaskUpdate={handleTaskUpdate} onOperatorSelect={handleOperatorSelect} columnVisibility={ganttColumnVisibility} onGanttInteractionChange={setIsGanttInteracting} onTaskReorder={handleTaskReorder} masterTasks={masterTasks} filters={filters} onFilterChange={handleFilterChange} onClearFilters={handleClearFilters} /> );
    }
  };

  const renderSidebarContent = () => {
    if (selectedTask) { return ( <TaskDetailSidebar task={selectedTask} allTasks={tasks} onUpdateTasks={handleSetTasks} onClose={handleSidebarClose} operatorContext={selectedOperator} onBackToOperator={selectedOperator ? handleBackToOperator : undefined} /> ); }
    if (selectedOperator) { return ( <OperatorDetailSidebar operatorName={selectedOperator} assignedTasks={operatorTasks} onTaskSelect={handleOperatorTaskSelect} onClose={handleSidebarClose} /> ); }
    return null;
  };

  const currentColumnConfig = columnVisibilityConfig[currentView as keyof typeof columnVisibilityConfig];

  return (
    <div className="h-screen w-screen bg-slate-900 text-white flex font-sans">
      <NavigationSidebar 
        currentView={currentView}
        onNavigate={handleNavigate}
        isDashboardOpen={isDashboardOpen}
        onToggleDashboard={handleToggleDashboard}
      />
      <div className="flex-1 flex flex-col min-w-0">
        <DashboardHeader
            pageTitle={pageTitles[currentView] || t('pageTitle.gantt')}
            currentView={currentView}
            columnVisibility={currentColumnConfig?.state}
            columnConfig={currentColumnConfig?.config}
            isColumnMenuOpen={isColumnMenuOpen}
            onSetIsColumnMenuOpen={setIsColumnMenuOpen}
            onColumnToggle={handleColumnToggle}
        />
        <main className="flex-grow p-4 overflow-auto bg-slate-800">
          {renderCurrentView()}
        </main>
      </div>

      <Sidebar isOpen={isModalSidebarOpen} onClose={handleSidebarClose}>
        {renderSidebarContent()}
      </Sidebar>

      <div className={`flex-shrink-0 transition-all duration-300 ease-in-out ${isDashboardOpen ? 'w-[26rem]' : 'w-0'}`}>
        {isDashboardOpen && (
          <div className="p-4 h-full w-[26rem]">
            <DashboardSidebar
                tasks={tasks}
                filters={filters}
                onFilterChange={handleFilterChange}
                onClearFilters={handleClearFilters}
                allOperators={operators}
                allStatuses={Object.values(TaskStatus)}
                onClose={handleToggleDashboard}
            />
          </div>
        )}
      </div>

    </div>
  );
};

