interface FiltersState {
  program: string[];
  subProgram: string[];
  showCriticalOnly: boolean;
  [key: string]: any; // Allow other filter properties
}

interface GanttFiltersProps {
    masterTasks: MasterTask[];
    filters: FiltersState;
    onFilterChange: (filterType: keyof FiltersState, value: string | boolean) => void;
    onClearFilters: () => void;
}

const FilterDropdown: React.FC<{ label: string; options: string[]; selected: string[]; onToggle: (option: string) => void; }> = ({ label, options, selected, onToggle }) => {
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const isActive = selected.length > 0;
    return (
        <div className="relative" ref={dropdownRef}>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={`flex items-center gap-2 px-3 py-1.5 text-sm font-semibold rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-900 ${
                    isActive ? 'bg-cyan-500 text-white hover:bg-cyan-600 focus:ring-cyan-400' : 'bg-slate-700 text-slate-200 hover:bg-slate-600 focus:ring-slate-500'
                }`}
            >
                {label}
                {isActive && <span className="bg-cyan-700 text-white text-xs font-bold rounded-full px-2">{selected.length}</span>}
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" /></svg>
            </button>
            {isOpen && (
                <div className="absolute top-full left-0 mt-2 w-64 bg-slate-800/90 backdrop-blur-sm border border-slate-700 rounded-lg shadow-2xl p-2 z-50">
                    <div className="max-h-60 overflow-y-auto pr-1">
                        {options.map(option => (
                            <label key={option} className="flex items-center gap-3 p-2 rounded-md hover:bg-slate-700 cursor-pointer">
                                <input type="checkbox" className="h-4 w-4 rounded bg-slate-600 border-slate-500 text-cyan-500 focus:ring-cyan-500" checked={selected.includes(option)} onChange={() => onToggle(option)} />
                                <span className="text-sm text-slate-200">{option}</span>
                            </label>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

const GanttFilters: React.FC<GanttFiltersProps> = ({ masterTasks, filters, onFilterChange, onClearFilters }) => {
    const { t } = useLocalization();
    const uniquePrograms = useMemo(() => Array.from(new Set(masterTasks.map(mt => mt.program))), [masterTasks]);
    const uniqueSubPrograms = useMemo(() => {
        const relevantSubPrograms = masterTasks
            .filter(mt => filters.program.length === 0 || filters.program.includes(mt.program))
            .map(mt => mt.subProgram);
        return Array.from(new Set(relevantSubPrograms));
    }, [masterTasks, filters.program]);

    const hasActiveFilters = filters.program.length > 0 || filters.subProgram.length > 0 || filters.showCriticalOnly;

    return (
        <div className="p-4 bg-slate-900/50 border-b border-slate-700/80 flex items-center gap-4 flex-wrap">
            <FilterDropdown label={t('ganttFilters.program')} options={uniquePrograms} selected={filters.program} onToggle={(option) => onFilterChange('program', option)} />
            <FilterDropdown label={t('ganttFilters.subProgram')} options={uniqueSubPrograms} selected={filters.subProgram} onToggle={(option) => onFilterChange('subProgram', option)} />
             <label className="flex items-center gap-3 p-2 rounded-lg bg-slate-700 hover:bg-slate-600 cursor-pointer transition-colors">
                <input type="checkbox" className="h-4 w-4 rounded bg-slate-600 border-slate-500 text-cyan-500 focus:ring-cyan-500" checked={filters.showCriticalOnly} onChange={(e) => onFilterChange('showCriticalOnly', e.target.checked)} />
                <span className="text-sm font-semibold text-slate-200">{t('ganttFilters.criticalOnly')}</span>
            </label>
             {hasActiveFilters && (
                <button onClick={onClearFilters} className="text-sm font-semibold text-red-400 hover:text-red-300 transition-colors">{t('ganttFilters.clear')}</button>
            )}
        </div>
    );
};


