const CalendarIcon = () => <svg {...iconProps}><rect width="18" height="18" x="3" y="4" rx="2" ry="2"/><line x1="16" x2="16" y1="2" y2="6"/><line x1="8" x2="8" y1="2" y2="6"/><line x1="3" x2="21" y1="10" y2="10"/></svg>;
const ClockIcon = () => <svg {...iconProps}><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>;

const GanttChart: React.FC<GanttChartProps> = ({ tasks, allTasks, onTaskSelect, onOperatorSelect, selectedTaskId, onTaskUpdate, columnVisibility, onGanttInteractionChange, onTaskReorder, masterTasks, filters, onFilterChange, onClearFilters }) => {
  const { t, getDaysOfWeek, getTaskStatusName } = useLocalization();
  const [interaction, setInteraction] = useState<InteractionState | null>(null);
  const [transientTask, setTransientTask] = useState<Task | null>(null);
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0, scrollLeft: 0, scrollTop: 0 });
  const [activeInteractionTaskId, setActiveInteractionTaskId] = useState<number | null>(null);
  const [draggedTaskId, setDraggedTaskId] = useState<number | null>(null);
  const [dragOverTaskId, setDragOverTaskId] = useState<number | null>(null);

  const [contextMenu, setContextMenu] = useState<ContextMenuState>({ isOpen: false, x: 0, y: 0, task: null });
  const contextMenuRef = useRef<HTMLDivElement>(null);


  const columnConfig = useMemo(() => [
    { id: 'task', label: t('columns.task'), width: 220, alwaysVisible: true, icon: <ClipboardListIcon /> },
    { id: 'orderId', label: t('columns.orderId'), width: 100, icon: <HashtagIcon /> },
    { id: 'quality', label: t('columns.quality'), width: 50, icon: <ShieldCheckIcon /> },
    { id: 'realisation', label: t('columns.realisation'), width: 80, icon: <LineChartIcon /> },
    { id: 'assignedTo', label: t('columns.assignedTo'), width: 120, icon: <UserCircleIcon /> },
    { id: 'status', label: t('columns.status'), width: 110, icon: <TagIcon /> },
    { id: 'progress', label: t('columns.progress'), width: 120, icon: <ChartPieIcon /> },
    { id: 'dueBy', label: t('columns.dueBy'), width: 100, icon: <CalendarIcon /> },
    { id: 'duration', label: t('columns.duration'), width: 70, icon: <ClockIcon /> },
  ], [t]);

  const [columnWidths, setColumnWidths] = useState(() => 
    Object.fromEntries(columnConfig.map(c => [c.id, c.width]))
  );
  const [resizingColumn, setResizingColumn] = useState<ColumnResizeState | null>(null);

  const [statusPopup, setStatusPopup] = useState<{ isOpen: boolean; task: Task | null; position: { top: number; left: number }; }>({ isOpen: false, task: null, position: { top: 0, left: 0 } });
  const statusPopupRef = useRef<HTMLDivElement>(null);

  const [scrollTop, setScrollTop] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);

  const DAYS_OF_WEEK = getDaysOfWeek('long');
  const DAYS_OF_WEEK_SHORT = getDaysOfWeek('short');
  const TOTAL_HOURS = DAYS_OF_WEEK.length * WORK_DAY_HOURS;

  const visibleColumns = useMemo(() => 
    columnConfig.filter(c => c.alwaysVisible || columnVisibility[c.id as keyof typeof columnVisibility])
  , [columnVisibility, columnConfig]);

  const leftColWidths = useMemo(() => visibleColumns.map(c => columnWidths[c.id]), [visibleColumns, columnWidths]);
  const totalLeftWidth = useMemo(() => leftColWidths.reduce((a, b) => a + b, 0), [leftColWidths]);
  const timelineWidth = TOTAL_HOURS * HOUR_WIDTH;
  const totalGridWidth = totalLeftWidth + timelineWidth;

  const gridRef = useRef<HTMLDivElement>(null);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
    setScrollLeft(e.currentTarget.scrollLeft);
  };

  useEffect(() => {
    if (gridRef.current) {
      setContainerHeight(gridRef.current.clientHeight);
    }
  }, []);

  // Notify parent about interaction state
  useEffect(() => {
    const isInteracting = interaction !== null || isPanning || resizingColumn !== null || draggedTaskId !== null;
    onGanttInteractionChange(isInteracting);
  }, [interaction, isPanning, resizingColumn, onGanttInteractionChange, draggedTaskId]);

  const handleMouseMove = useCallback((event: MouseEvent) => {
    if (!interaction) return;

    const dx = event.clientX - interaction.initialMouseX;
    let updatedTask = { ...interaction.task };

    if (interaction.type === 'drag') {
      const hourDelta = Math.round(dx / HOUR_WIDTH);
      const newTotalStartHour = (interaction.initialDay * WORK_DAY_HOURS) + interaction.initialStartHour + hourDelta;
      const maxTotalStartHour = TOTAL_HOURS - updatedTask.duration;
      const clampedTotalStartHour = Math.max(0, Math.min(newTotalStartHour, maxTotalStartHour));
      updatedTask.day = Math.floor(clampedTotalStartHour / WORK_DAY_HOURS);
      updatedTask.startHour = clampedTotalStartHour % WORK_DAY_HOURS;
    } else if (interaction.type === 'progress') {
        const taskWidthPx = updatedTask.duration * HOUR_WIDTH;
        if (taskWidthPx > 0) {
            const progressDelta = (dx / taskWidthPx) * 100;
            const newProgress = interaction.initialProgress + progressDelta;
            updatedTask.progress = Math.max(0, Math.min(100, Math.round(newProgress)));
        }
    } else if (interaction.type === 'resize-start') {
        const hourDelta = Math.round(dx / HOUR_WIDTH);
        const initialTotalStartHour = (interaction.initialDay * WORK_DAY_HOURS) + interaction.initialStartHour;
        const initialTotalEndHour = initialTotalStartHour + interaction.initialDuration;

        let newTotalStartHour = initialTotalStartHour + hourDelta;

        newTotalStartHour = Math.max(0, Math.min(newTotalStartHour, initialTotalEndHour - 1));

        const newDuration = initialTotalEndHour - newTotalStartHour;

        updatedTask.day = Math.floor(newTotalStartHour / WORK_DAY_HOURS);
        updatedTask.startHour = newTotalStartHour % WORK_DAY_HOURS;
        updatedTask.duration = newDuration;
    } else if (interaction.type === 'resize-end') {
        const hourDelta = Math.round(dx / HOUR_WIDTH);
        const newDuration = interaction.initialDuration + hourDelta;

        const totalStartHour = updatedTask.day * WORK_DAY_HOURS + updatedTask.startHour;
        const maxDuration = TOTAL_HOURS - totalStartHour;

        updatedTask.duration = Math.max(1, Math.min(newDuration, maxDuration));
    }
    setTransientTask(updatedTask);
  }, [interaction, TOTAL_HOURS]);

  const handleMouseUp = useCallback(() => {
    if (interaction && transientTask) {
        onTaskUpdate(transientTask);
    }
    setInteraction(null);
    setTransientTask(null);
    setActiveInteractionTaskId(null);
  }, [interaction, transientTask, onTaskUpdate]);

  const handlePanStart = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.button !== 0 || (e.target as HTMLElement).closest('.group') || (e.target as HTMLElement).closest('.gantt-left-cell') || (e.target as HTMLElement).closest('.header-cell') || (e.target as HTMLElement).closest('svg')) {
        return;
    }

    e.preventDefault();
    setIsPanning(true);
    setPanStart({
        x: e.clientX,
        y: e.clientY,
        scrollLeft: gridRef.current?.scrollLeft || 0,
        scrollTop: gridRef.current?.scrollTop || 0,
    });
  };

  const handleColumnResizeStart = useCallback((event: React.MouseEvent, columnId: string) => {
    event.preventDefault();
    event.stopPropagation();
    setResizingColumn({
        id: columnId,
        startX: event.clientX,
        startWidth: columnWidths[columnId],
    });
  }, [columnWidths]);

  const handleColumnResize = useCallback((event: MouseEvent) => {
    if (!resizingColumn) return;
    const dx = event.clientX - resizingColumn.startX;
    const newWidth = Math.max(60, resizingColumn.startWidth + dx); // Min width 60px
    setColumnWidths(prev => ({...prev, [resizingColumn.id]: newWidth}));
  }, [resizingColumn]);

  const handleColumnResizeEnd = useCallback(() => {
    setResizingColumn(null);
  }, []);

  const handleDragStart = useCallback((e: React.DragEvent, taskId: number) => {
      e.dataTransfer.setData('text/plain', taskId.toString());
      e.dataTransfer.effectAllowed = 'move';
      setDraggedTaskId(taskId);
  }, []);

  const handleDragOver = useCallback((e: React.DragEvent, taskId: number) => {
      e.preventDefault();
      if (taskId !== dragOverTaskId) {
          setDragOverTaskId(taskId);
      }
  }, [dragOverTaskId]);

  const handleDrop = useCallback((e: React.DragEvent, targetTaskId: number) => {
      e.preventDefault();
      if (draggedTaskId !== null && draggedTaskId !== targetTaskId) {
          onTaskReorder(draggedTaskId, targetTaskId);
      }
      setDraggedTaskId(null);
      setDragOverTaskId(null);
  }, [draggedTaskId, onTaskReorder]);

  const handleDragEnd = useCallback(() => {
      setDraggedTaskId(null);
      setDragOverTaskId(null);
  }, []);


  useEffect(() => {
    const ganttElement = gridRef.current;
    const handleWindowMouseMove = (e: MouseEvent) => {
        if (resizingColumn) {
            handleColumnResize(e);
        } else if (isPanning && ganttElement) {
            e.preventDefault();
            const dx = e.clientX - panStart.x;
            const dy = e.clientY - panStart.y;
            ganttElement.scrollLeft = panStart.scrollLeft - dx;
            ganttElement.scrollTop = panStart.scrollTop - dy;
        } else if (interaction) {
            handleMouseMove(e);
        }
    };
    const handleWindowMouseUp = () => {
        setIsPanning(false);
        if (interaction) {
            handleMouseUp();
        }
        if (resizingColumn) {
            handleColumnResizeEnd();
        }
    };
    window.addEventListener('mousemove', handleWindowMouseMove);
    window.addEventListener('mouseup', handleWindowMouseUp);
    return () => {
        window.removeEventListener('mousemove', handleWindowMouseMove);
        window.removeEventListener('mouseup', handleWindowMouseUp);
    };
  }, [isPanning, panStart, interaction, handleMouseMove, handleMouseUp, resizingColumn, handleColumnResize, handleColumnResizeEnd]);

  useEffect(() => {
      const ganttElement = gridRef.current;
      if (!ganttElement) return;

      if (resizingColumn) {
          document.body.style.cursor = 'col-resize';
      } else if (isPanning) {
          document.body.style.cursor = 'grabbing';
          ganttElement.style.cursor = 'grabbing';
      } else if (interaction) {
          ganttElement.style.cursor = 'default';
          if (interaction.type === 'drag') document.body.style.cursor = 'move';
          else if (interaction.type === 'progress') document.body.style.cursor = 'col-resize';
          else if (interaction.type === 'resize-start') document.body.style.cursor = 'w-resize';
          else if (interaction.type === 'resize-end') document.body.style.cursor = 'e-resize';
      } else {
          document.body.style.cursor = 'default';
          ganttElement.style.cursor = 'default';
      }

      return () => { document.body.style.cursor = 'default'; };
  }, [isPanning, interaction, resizingColumn]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (statusPopup.isOpen && statusPopupRef.current && !statusPopupRef.current.contains(event.target as Node)) {
        setStatusPopup({ isOpen: false, task: null, position: { top: 0, left: 0 } });
      }
      if (contextMenu.isOpen && contextMenuRef.current && !contextMenuRef.current.contains(event.target as Node)) {
          setContextMenu(prev => ({ ...prev, isOpen: false }));
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [statusPopup.isOpen, contextMenu.isOpen]);

  const handleInteractionStart = (
    type: 'drag' | 'progress' | 'resize-start' | 'resize-end',
    event: React.MouseEvent,
    task: Task
  ) => {
    if (task.status === TaskStatus.Completed || task.status === TaskStatus.QualityOK || event.button !== 0) return;
    event.stopPropagation();
    setActiveInteractionTaskId(task.id);
    setInteraction({ 
        type, 
        task, 
        initialMouseX: event.clientX, 
        initialStartHour: task.startHour, 
        initialDay: task.day, 
        initialProgress: task.progress,
        initialDuration: task.duration
    });
    setTransientTask(task);
  };

  const handleStatusClick = (event: React.MouseEvent, task: Task) => {
    if (task.status === TaskStatus.QualityOK) return;
    event.stopPropagation();
    const rect = event.currentTarget.getBoundingClientRect();
    setStatusPopup({
      isOpen: true,
      task,
      position: { top: rect.bottom + 4, left: rect.left },
    });
  };

  const handleStatusChange = (newStatus: TaskStatus) => {
    if (statusPopup.task) {
      const updatedTask = { ...statusPopup.task, status: newStatus };
      if (newStatus === TaskStatus.Completed) {
        updatedTask.progress = 100;
      } else if (statusPopup.task.status === TaskStatus.Completed) {
        updatedTask.progress = 90;
      }
      onTaskUpdate(updatedTask);
    }
    setStatusPopup({ isOpen: false, task: null, position: { top: 0, left: 0 } });
  };

  const handleQualityCheck = (task: Task, isChecked: boolean) => {
      if (isChecked && task.status === TaskStatus.Completed) {
          onTaskUpdate({ ...task, status: TaskStatus.QualityOK });
      }
  };

  const handleContextMenuAction = (status: TaskStatus) => {
      if (contextMenu.task) {
          const updatedTask = { ...contextMenu.task, status };
          if (status === TaskStatus.Completed) {
              updatedTask.progress = 100;
          } else if (contextMenu.task.status === TaskStatus.Completed) {
              updatedTask.progress = 90; // Revert to in-progress state approximate
          }
          onTaskUpdate(updatedTask);
      }
      setContextMenu(prev => ({ ...prev, isOpen: false }));
  };

  const handleTaskContextMenu = (event: React.MouseEvent, task: Task) => {
      setContextMenu({
          isOpen: true,
          x: event.clientX,
          y: event.clientY,
          task
      });
  };

  const isTaskOverdue = (task: Task) => {
    const endTotalHour = (task.day * WORK_DAY_HOURS) + task.startHour + task.duration;
    const dueTotalHour = (task.dueDay * WORK_DAY_HOURS) + task.dueHour + 1; // Due by end of hour
    return endTotalHour > dueTotalHour;
  };

  const getFormattedTime = (hourIndex: number) => {
      const hour = hourIndex + 8; // 8 AM is our base
      return `${hour % 12 === 0 ? 12 : hour % 12}:00 ${hour >= 12 && hour < 24 ? 'PM' : 'AM'}`;
  };

  const renderCellContent = (task: Task, columnId: string) => {
    const isOverdueValue = isTaskOverdue(task);
    switch (columnId) {
        case 'task':
            return (
                <>
                    <div className={`w-1.5 h-full rounded-full mr-3 flex-shrink-0 ${task.isCritical ? 'bg-orange-400' : (isOverdueValue && task.status !== TaskStatus.Completed && task.status !== TaskStatus.QualityOK ? 'bg-red-500' : 'bg-transparent')}`}></div>
                    <span className="font-medium text-slate-100 truncate">{task.name}</span>
                </>
            );
        case 'orderId':
            return <span className="text-slate-400 font-mono text-sm">{task.orderId}</span>;
        case 'quality':
            const isQualityCheckable = task.status === TaskStatus.Completed;
            const isQualityOK = task.status === TaskStatus.QualityOK;
            return (
                <div className="w-full flex justify-center">
                    <input
                        type="checkbox"
                        checked={isQualityOK}
                        disabled={!isQualityCheckable && !isQualityOK}
                        onChange={(e) => handleQualityCheck(task, e.target.checked)}
                        onClick={(e) => e.stopPropagation()} // Prevent row selection
                        className="h-5 w-5 rounded bg-slate-600 border-slate-500 text-purple-500 focus:ring-purple-500 disabled:opacity-50 disabled:cursor-not-allowed"
                        title={isQualityCheckable ? t('gantt.quality.checkableTooltip') : isQualityOK ? t('gantt.quality.checkedTooltip') : t('gantt.quality.disabledTooltip')}
                    />
                </div>
            );
        case 'realisation':
            const realisedHours = (task.duration * task.progress) / 100;
            const isTrackingLate = isOverdueValue && task.progress < 100;
            const textColor = isTrackingLate ? 'text-red-400 font-bold' : 'text-green-400';
            return (
              <span className={`font-medium ${textColor}`}>
                {t('gantt.realisation.hours', realisedHours.toFixed(1))}
              </span>
            );
        case 'assignedTo':
            return (
                <button
                    onDoubleClick={(e) => {
                        e.stopPropagation();
                        onOperatorSelect(task.assignedTo);
                    }}
                    className="text-slate-300 truncate text-left w-full h-full hover:text-cyan-400 font-medium transition-colors"
                >
                    {task.assignedTo}
                </button>
            );
        case 'status':
            const statusColor = TASK_STATUS_COLORS[task.status];
            const isQualityOKStatus = task.status === TaskStatus.QualityOK;
            return (
                <button
                    onClick={(e) => handleStatusClick(e, task)}
                    disabled={isQualityOKStatus}
                    className={`w-full text-center px-2.5 py-1 text-xs font-bold rounded-full whitespace-nowrap ${statusColor.background} ${statusColor.text} ${!isQualityOKStatus && 'transition-all hover:ring-2 hover:ring-offset-2 hover:ring-offset-slate-800 hover:ring-cyan-400'} disabled:cursor-default disabled:hover:ring-0`}
                >
                    {getTaskStatusName(task.status)}
                </button>
            );
        case 'progress':
            let progressColor = 'bg-green-500';
            if (task.status === TaskStatus.QualityOK) {
                progressColor = 'bg-purple-500';
            } else if (task.progress === 100) {
                progressColor = 'bg-emerald-500';
            } else if (isOverdueValue) {
                progressColor = 'bg-red-500';
            }

            return (
                <div className="w-full flex items-center gap-2">
                    <div className="w-full bg-slate-600 rounded-full h-2">
                        <div 
                            className={`${progressColor} h-2 rounded-full transition-colors`} 
                            style={{ width: `${task.progress}%` }}
                        ></div>
                    </div>
                    <span className="text-xs font-mono text-slate-400 w-8 text-right">{task.progress}%</span>
                </div>
            );
        case 'dueBy':
            const dueDateString = `${DAYS_OF_WEEK_SHORT[task.dueDay]}`;
            const dueTime = getFormattedTime(task.dueHour + 1);
            return <span className="text-slate-300 text-sm font-medium">{`${dueDateString}, ${dueTime}`}</span>;
        case 'duration':
            return <span className="text-slate-300 font-medium">{t('gantt.duration.hours', task.duration)}</span>;
        default:
            return null;
    }
  };

  // 1. Stable map of all tasks with their indices. Re-computes only when tasks list changes (order/add/remove).
  const taskMapWithIndex = useMemo(() => new Map(tasks.map((t, i) => [t.id, { task: t, index: i }])), [tasks]);

  // VIRTUALIZATION LOGIC
  const startIndex = Math.max(0, Math.floor(scrollTop / TASK_ROW_HEIGHT) - OVERSCAN_COUNT);
  const visibleItemCount = containerHeight ? Math.ceil(containerHeight / TASK_ROW_HEIGHT) : 0;
  const endIndex = Math.min(tasks.length, startIndex + visibleItemCount + OVERSCAN_COUNT * 2);

  const visibleItems = useMemo(() => {
    const items = [];
    for (let i = startIndex; i < endIndex; i++) {
        let task = tasks[i];
        if (transientTask && task.id === transientTask.id) {
            task = transientTask;
        }
        items.push({ task, index: i });
    }
    return items;
  }, [startIndex, endIndex, tasks, transientTask]);

  return (
    <div className="bg-slate-800 text-white rounded-2xl shadow-2xl h-full flex flex-col overflow-hidden">
        <GanttFilters masterTasks={masterTasks} filters={filters} onFilterChange={onFilterChange} onClearFilters={onClearFilters} />
        <div 
            ref={gridRef} 
            onScroll={handleScroll}
            className="overflow-auto flex-grow w-full select-none relative"
        >
            {/* STICKY HEADER */}
            <div 
                className="sticky top-0 z-20 flex"
                style={{ width: totalGridWidth, height: HEADER_HEIGHT }}
            >
                {/* Left Columns Header */}
                <div className="flex flex-shrink-0 bg-sky-900">
                    {visibleColumns.map((col) => (
                        <div key={col.id} title={col.label} className={`group relative font-semibold text-slate-100 text-sm p-3 flex flex-col items-center justify-center text-center border-b-2 border-r border-sky-800 header-cell`} style={{width: columnWidths[col.id], height: HEADER_HEIGHT}}>
                            <div className="flex items-center gap-2">
                                {col.icon}
                            </div>
                            <span className="transition-colors group-hover:text-cyan-400 mt-1">{col.label}</span>
                            <div
                                onMouseDown={(e) => handleColumnResizeStart(e, col.id)}
                                className="absolute top-0 right-0 h-full w-2 cursor-col-resize opacity-0 group-hover:opacity-100 hover:bg-cyan-500/30 transition-all"
                                title={t('gantt.resizeColumn', col.label)}
                            />
                        </div>
                    ))}
                </div>
                {/* Timeline Header */}
                <div className="flex-1 flex flex-col bg-sky-900" style={{height: HEADER_HEIGHT}}>
                    <div className="flex flex-1">
                    {DAYS_OF_WEEK.map((day) => (
                        <div key={day} className="flex items-center justify-center text-slate-100 font-bold text-base border-b-2 border-sky-800/80" style={{width: WORK_DAY_HOURS * HOUR_WIDTH}}>{day}</div>
                    ))}
                    </div>
                    <div className="flex flex-1">
                    {Array.from({length: TOTAL_HOURS}).map((_, hourIndex) => (
                        <div key={`h-${hourIndex}`} className="flex items-center justify-center text-slate-300 text-xs border-b border-r border-sky-800/80" style={{width: HOUR_WIDTH}}>{WORK_HOURS[hourIndex % WORK_DAY_HOURS]}</div>
                    ))}
                    </div>
                </div>
            </div>

            {/* VIRTUALIZED BODY */}
            <div style={{ height: tasks.length * TASK_ROW_HEIGHT, width: totalGridWidth, position: 'relative' }} onDragOver={(e) => e.preventDefault()}>

                {/* Dependency Lines */}
                <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ top: HEADER_HEIGHT }}>
                    <defs>
                        <marker id="arrowhead" markerWidth="6" markerHeight="4" refX="5" refY="2" orient="auto">
                            <polygon points="0 0, 6 2, 0 4" fill="#a78bfa" />
                        </marker>
                    </defs>
                    {visibleItems.map(({ task: dependentTask, index: dependentIndex }) =>
                        (dependentTask.dependencies || []).map(prereqId => {
                            const prereqInfo = taskMapWithIndex.get(prereqId);

                            // Prerequisite is not visible (filtered out), so don't draw the line.
                            if (!prereqInfo) {
                                return null;
                            }

                            let prereqTask = prereqInfo.task;
                            // If the prerequisite is active transient task, use that position
                            if (transientTask && prereqTask.id === transientTask.id) {
                                prereqTask = transientTask;
                            }

                            const startY = prereqInfo.index * TASK_ROW_HEIGHT + TASK_ROW_HEIGHT / 2 - scrollTop;
                            const endY = dependentIndex * TASK_ROW_HEIGHT + TASK_ROW_HEIGHT / 2 - scrollTop;

                            // Optimization: Only render if both tasks are somewhat in view
                            if ((startY < -50 && endY < -50) || (startY > containerHeight + 50 && endY > containerHeight + 50)) {
                                return null;
                            }

                            const startX = totalLeftWidth + (prereqTask.day * WORK_DAY_HOURS + prereqTask.startHour + prereqTask.duration) * HOUR_WIDTH;
                            const endX = totalLeftWidth + (dependentTask.day * WORK_DAY_HOURS + dependentTask.startHour) * HOUR_WIDTH;

                            const c1X = startX + HOUR_WIDTH * 1.5;
                            const c1Y = startY;
                            const c2X = endX - HOUR_WIDTH * 1.5;
                            const c2Y = endY;

                            return (
                                <path
                                    key={`${prereqId}-${dependentTask.id}`}
                                    d={`M ${startX} ${startY} C ${c1X} ${c1Y}, ${c2X} ${c2Y}, ${endX - 8} ${endY}`}
                                    stroke="#a78bfa"
                                    strokeWidth="2"
                                    fill="none"
                                    strokeOpacity="0.8"
                                    markerEnd="url(#arrowhead)"
                                />
                            );
                        })
                    )}
                </svg>

                {visibleItems.map(({ task, index }) => {
                    const isBeingDragged = draggedTaskId === task.id;
                    const isDragTarget = dragOverTaskId === task.id;
                    return (
                        <div
                            key={task.id}
                            draggable
                            onDragStart={(e) => handleDragStart(e, task.id)}
                            onDragOver={(e) => handleDragOver(e, task.id)}
                            onDrop={(e) => handleDrop(e, task.id)}
                            onDragEnd={handleDragEnd}
                            onDragLeave={() => setDragOverTaskId(null)}
                            style={{
                                position: 'absolute',
                                top: index * TASK_ROW_HEIGHT,
                                left: 0,
                                height: TASK_ROW_HEIGHT,
                                width: totalGridWidth,
                            }}
                            className={`flex items-stretch cursor-grab ${isBeingDragged ? 'opacity-50' : ''} ${isDragTarget ? 'bg-cyan-500/20' : ''}`}
                        >
                            {/* Left Cells */}
                            <div 
                                className={`flex flex-shrink-0 ${
                                    task.id === selectedTaskId || task.id === activeInteractionTaskId ? 'bg-slate-700' : (index % 2 !== 0 ? 'bg-slate-900' : 'bg-slate-800')
                                } transition-colors duration-200`}
                                style={{ width: totalLeftWidth }}
                            >
                                {visibleColumns.map(col => (
                                    <div
                                        key={col.id}
                                        onDoubleClick={() => onTaskSelect(task)}
                                        className="flex items-center p-2 border-b border-r border-slate-700/50 gantt-left-cell"
                                        style={{width: columnWidths[col.id]}}
                                    >
                                        {renderCellContent(task, col.id)}
                                    </div>
                                ))}
                            </div>

                            {/* Right Timeline Pane */}
                            <div
                                style={{ 
                                    width: timelineWidth, 
                                    height: TASK_ROW_HEIGHT,
                                    backgroundImage: `linear-gradient(to right, transparent 39px, rgba(51, 65, 85, 0.3) 39px, rgba(51, 65, 85, 0.3) 40px)`,
                                    backgroundSize: `${HOUR_WIDTH}px 100%`
                                }}
                                className={`relative border-b border-slate-700/50 ${
                                    task.id === selectedTaskId || task.id === activeInteractionTaskId ? 'bg-slate-700' : (index % 2 !== 0 ? 'bg-slate-900' : 'bg-slate-800')
                                } transition-colors duration-200`}
                            >
                                <TaskBlock
                                    task={task}
                                    onInteractionStart={handleInteractionStart}
                                    onDoubleClick={onTaskSelect}
                                    onContextMenu={handleTaskContextMenu}
                                    isSelected={task.id === selectedTaskId || task.id === activeInteractionTaskId}
                                    isOverdue={isTaskOverdue(task)}
                                    left={ (task.day * WORK_DAY_HOURS + task.startHour) * HOUR_WIDTH}
                                    width={task.duration * HOUR_WIDTH}
                                />
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>

      {/* Status Popup (Left Column) */}
      {statusPopup.isOpen && statusPopup.task && (
        <div
          ref={statusPopupRef}
          className="fixed z-50 bg-slate-900/80 backdrop-blur-sm border border-slate-600 rounded-lg shadow-2xl p-2"
          style={{ top: statusPopup.position.top, left: statusPopup.position.left }}
        >
          <div className="flex flex-col gap-1 w-36">
            {Object.values(TaskStatus).filter(s => s !== TaskStatus.QualityOK).map(status => (
              <button
                key={status}
                onClick={() => handleStatusChange(status)}
                className={`px-3 py-1.5 text-sm text-left rounded-md w-full ${TASK_STATUS_COLORS[status].text} ${TASK_STATUS_COLORS[status].background} hover:brightness-125 transition-all disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:brightness-100`}
                disabled={status === statusPopup.task?.status}
              >
                {getTaskStatusName(status)}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Context Menu (Task Blocks) */}
      {contextMenu.isOpen && contextMenu.task && (
          <div
              ref={contextMenuRef}
              className="fixed z-50 bg-slate-900/90 backdrop-blur-md border border-slate-700 rounded-xl shadow-2xl p-1.5 min-w-[160px] animate-fade-in-up"
              style={{ top: contextMenu.y, left: contextMenu.x }}
          >
              <div className="px-3 py-2 text-xs font-bold text-slate-400 uppercase tracking-wider border-b border-slate-700 mb-1">
                  {t('columns.status')}
              </div>
              <div className="flex flex-col gap-1">
                  {Object.values(TaskStatus).filter(s => s !== TaskStatus.QualityOK).map(status => (
                      <button
                          key={status}
                          onClick={() => handleContextMenuAction(status)}
                          className={`px-3 py-2 text-sm text-left rounded-lg w-full flex items-center gap-2 transition-all ${
                              contextMenu.task?.status === status 
                                  ? 'bg-slate-700 text-white' 
                                  : 'text-slate-300 hover:bg-slate-800 hover:text-white'
                          }`}
                      >
                          <div className={`w-2 h-2 rounded-full ${TASK_STATUS_COLORS[status].background.replace('bg-', 'bg-')}`}></div>
                          {getTaskStatusName(status)}
                      </button>
                  ))}
              </div>
          </div>
      )}
    </div>
  );
};

export default GanttChart;

    case 'taskdatabase': return ( <TaskDatabasePage allTasks={tasks} masterTasks={masterTasks} onUpdateMasterTasks={handleSetMasterTasks} columnVisibility={taskDatabaseColumnVisibility} /> );
    case 'gantt':
    default: return ( <GanttChart tasks={visibleTasks} allTasks={tasks} allOperators={operators} onTaskSelect={handleGanttTaskSelect} selectedTaskId={selectedTask?.id} onTaskUpdate={handleTaskUpdate} onOperatorSelect={handleOperatorSelect} columnVisibility={ganttColumnVisibility} onGanttInteractionChange={setIsGanttInteracting} onTaskReorder={handleTaskReorder} masterTasks={masterTasks} filters={filters} onFilterChange={handleFilterChange} onClearFilters={handleClearFilters} /> );
  }
};

const renderSidebarContent = () => {

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Task, TaskStatus, MasterTask } from '../types';
import { TASK_STATUS_COLORS, WORK_DAY_HOURS, WORK_HOURS } from '../constants';
import TaskBlock from './TaskBlock';
import { useLocalization } from '../contexts/LocalizationContext';

interface FiltersState {
  program: string[];
  subProgram: string[];
  operator: string[];
  showCriticalOnly: boolean;
  [key: string]: any; // Allow other filter properties
}

interface GanttFiltersProps {
    masterTasks: MasterTask[];
    allOperators: string[];
    filters: FiltersState;
    onFilterChange: (filterType: keyof FiltersState, value: string | boolean) => void;
    onClearFilters: () => void;
}

const FilterDropdown: React.FC<{ label: string; options: string[]; selected: string[]; onToggle: (option: string) => void; }> = ({ label, options, selected, onToggle }) => {
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const isActive = selected.length > 0;
    return (
        <div className="relative" ref={dropdownRef}>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={`flex items-center gap-2 px-3 py-1.5 text-sm font-semibold rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-900 ${
                    isActive ? 'bg-cyan-500 text-white hover:bg-cyan-600 focus:ring-cyan-400' : 'bg-slate-700 text-slate-200 hover:bg-slate-600 focus:ring-slate-500'
                }`}
            >
                {label}
                {isActive && <span className="bg-cyan-700 text-white text-xs font-bold rounded-full px-2">{selected.length}</span>}
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" /></svg>
            </button>
            {isOpen && (
                <div className="absolute top-full left-0 mt-2 w-64 bg-slate-800/90 backdrop-blur-sm border border-slate-700 rounded-lg shadow-2xl p-2 z-50">
                    <div className="max-h-60 overflow-y-auto pr-1">
                        {options.map(option => (
                            <label key={option} className="flex items-center gap-3 p-2 rounded-md hover:bg-slate-700 cursor-pointer">
                                <input type="checkbox" className="h-4 w-4 rounded bg-slate-600 border-slate-500 text-cyan-500 focus:ring-cyan-500" checked={selected.includes(option)} onChange={() => onToggle(option)} />
                                <span className="text-sm text-slate-200">{option}</span>
                            </label>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

const GanttFilters: React.FC<GanttFiltersProps> = ({ masterTasks, allOperators, filters, onFilterChange, onClearFilters }) => {
    const { t } = useLocalization();
    const uniquePrograms = useMemo(() => Array.from(new Set(masterTasks.map(mt => mt.program))), [masterTasks]);
    const uniqueSubPrograms = useMemo(() => {
        const relevantSubPrograms = masterTasks
            .filter(mt => filters.program.length === 0 || filters.program.includes(mt.program))
            .map(mt => mt.subProgram);
        return Array.from(new Set(relevantSubPrograms));
    }, [masterTasks, filters.program]);

    const hasActiveFilters = filters.program.length > 0 || filters.subProgram.length > 0 || filters.operator.length > 0 || filters.showCriticalOnly;

    return (
        <div className="p-4 bg-slate-900/50 border-b border-slate-700/80 flex items-center gap-4 flex-wrap">
            <FilterDropdown label={t('ganttFilters.program')} options={uniquePrograms} selected={filters.program} onToggle={(option) => onFilterChange('program', option)} />
            <FilterDropdown label={t('ganttFilters.subProgram')} options={uniqueSubPrograms} selected={filters.subProgram} onToggle={(option) => onFilterChange('subProgram', option)} />
            <FilterDropdown label={t('ganttFilters.operator')} options={allOperators} selected={filters.operator || []} onToggle={(option) => onFilterChange('operator', option)} />
             <label className="flex items-center gap-3 p-2 rounded-lg bg-slate-700 hover:bg-slate-600 cursor-pointer transition-colors">
                <input type="checkbox" className="h-4 w-4 rounded bg-slate-600 border-slate-500 text-cyan-500 focus:ring-cyan-500" checked={filters.showCriticalOnly} onChange={(e) => onFilterChange('showCriticalOnly', e.target.checked)} />
                <span className="text-sm font-semibold text-slate-200">{t('ganttFilters.criticalOnly')}</span>
            </label>
             {hasActiveFilters && (
                <button onClick={onClearFilters} className="text-sm font-semibold text-red-400 hover:text-red-300 transition-colors">{t('ganttFilters.clear')}</button>
            )}
        </div>
    );
};


interface GanttChartProps {
  tasks: Task[];
  allTasks: Task[]; // Full list for dependency lookups
  allOperators: string[];
  onTaskSelect: (task: Task) => void;
  onOperatorSelect: (operatorName: string) => void;
  selectedTaskId?: number | null;
  onTaskUpdate: (task: Task) => void;
  columnVisibility: { [key: string]: boolean };
  onGanttInteractionChange: (isInteracting: boolean) => void;
  onTaskReorder: (draggedTaskId: number, targetTaskId: number) => void;
  masterTasks: MasterTask[];
  filters: FiltersState;
  onFilterChange: (filterType: keyof FiltersState, value: string | boolean) => void;
  onClearFilters: () => void;
}

interface InteractionState {
  type: 'drag' | 'progress' | 'resize-start' | 'resize-end';
  task: Task;
  initialMouseX: number;
  initialStartHour: number;
  initialDay: number;
  initialProgress: number;
  initialDuration: number;
}

interface ColumnResizeState {
  id: string;
  startX: number;
  startWidth: number;
}

interface ContextMenuState {
    isOpen: boolean;
    x: number;
    y: number;
    task: Task | null;
}


const HOUR_WIDTH = 40;
const TASK_ROW_HEIGHT = 36;
const HEADER_HEIGHT = 80;
const OVERSCAN_COUNT = 5; // Number of items to render above and below the viewport

// Icon definitions
const iconProps = { className: "h-5 w-5 text-slate-300 group-hover:text-cyan-400 transition-colors", strokeWidth: 2, fill: "none", viewBox: "0 0 24 24", stroke: "currentColor", strokeLinecap: "round" as const, strokeLinejoin: "round" as const };

const ClipboardListIcon = () => <svg {...iconProps}><rect width="8" height="4" x="8" y="2" rx="1" ry="1"/><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><path d="M12 11h4"/><path d="M12 16h4"/><path d="M8 11h.01"/><path d="M8 16h.01"/></svg>;
const HashtagIcon = () => <svg {...iconProps}><line x1="4" x2="20" y1="9" y2="9"/><line x1="4" x2="20" y1="15" y2="15"/><line x1="10" x2="8" y1="3" y2="21"/><line x1="16" x2="14" y1="3" y2="21"/></svg>;
const ShieldCheckIcon = () => <svg {...iconProps}><path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z"/><path d="m9 12 2 2 4-4"/></svg>;
const LineChartIcon = () => <svg {...iconProps}><path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-3 3"/></svg>;
const UserCircleIcon = () => <svg {...iconProps}><circle cx="12" cy="12" r="10"/><circle cx="12" cy="10" r="3"/><path d="M7 20.662V19a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v1.662"/></svg>;
const TagIcon = () => <svg {...iconProps}><path d="M12.586 2.586A2 2 0 0 0 11.172 2H4a2 2 0 0 0-2 2v7.172a2 2 0 0 0 .586 1.414l5 5a2 2 0 0 0 2.828 0l7.172-7.172a2 2 0 0 0 0-2.828l-5-5A2 2 0 0 0 12.586 2.586Z"/><circle cx="7.5" cy="7.5" r=".5" fill="currentColor"/></svg>;
const ChartPieIcon = () => <svg {...iconProps}><path d="M21.21 15.89A10 10 0 1 1 8 2.83"/><path d="M22 12A10 10 0 0 0 12 2v10z"/></svg>;
const CalendarIcon = () => <svg {...iconProps}><rect width="18" height="18" x="3" y="4" rx="2" ry="2"/><line x1="16" x2="16" y1="2" y2="6"/><line x1="8" x2="8" y1="2" y2="6"/><line x1="3" x2="21" y1="10" y2="10"/></svg>;
const ClockIcon = () => <svg {...iconProps}><circle cx="12" cy="12" r="10"/><circle cx="12" cy="10" r="3"/><polyline points="12 6 12 12 16 14"/></svg>;

const GanttChart: React.FC<GanttChartProps> = ({ tasks, allTasks, allOperators, onTaskSelect, onOperatorSelect, selectedTaskId, onTaskUpdate, columnVisibility, onGanttInteractionChange, onTaskReorder, masterTasks, filters, onFilterChange, onClearFilters }) => {
  const { t, getDaysOfWeek, getTaskStatusName } = useLocalization();
  const [interaction, setInteraction] = useState<InteractionState | null>(null);
  const [transientTask, setTransientTask] = useState<Task | null>(null);
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0, scrollLeft: 0, scrollTop: 0 });
  const [activeInteractionTaskId, setActiveInteractionTaskId] = useState<number | null>(null);
  const [draggedTaskId, setDraggedTaskId] = useState<number | null>(null);
  const [dragOverTaskId, setDragOverTaskId] = useState<number | null>(null);

  const [contextMenu, setContextMenu] = useState<ContextMenuState>({ isOpen: false, x: 0, y: 0, task: null });
  const contextMenuRef = useRef<HTMLDivElement>(null);


  const columnConfig = useMemo(() => [
    { id: 'task', label: t('columns.task'), width: 220, alwaysVisible: true, icon: <ClipboardListIcon /> },
    { id: 'orderId', label: t('columns.orderId'), width: 100, icon: <HashtagIcon /> },
    { id: 'quality', label: t('columns.quality'), width: 50, icon: <ShieldCheckIcon /> },
    { id: 'realisation', label: t('columns.realisation'), width: 80, icon: <LineChartIcon /> },
    { id: 'assignedTo', label: t('columns.assignedTo'), width: 120, icon: <UserCircleIcon /> },
    { id: 'status', label: t('columns.status'), width: 110, icon: <TagIcon /> },
    { id: 'progress', label: t('columns.progress'), width: 120, icon: <ChartPieIcon /> },
    { id: 'dueBy', label: t('columns.dueBy'), width: 100, icon: <CalendarIcon /> },
    { id: 'duration', label: t('columns.duration'), width: 70, icon: <ClockIcon /> },
  ], [t]);

  const [columnWidths, setColumnWidths] = useState(() => 
    Object.fromEntries(columnConfig.map(c => [c.id, c.width]))
  );
  const [resizingColumn, setResizingColumn] = useState<ColumnResizeState | null>(null);

  const [statusPopup, setStatusPopup] = useState<{ isOpen: boolean; task: Task | null; position: { top: number; left: number }; }>({ isOpen: false, task: null, position: { top: 0, left: 0 } });
  const statusPopupRef = useRef<HTMLDivElement>(null);

  const [scrollTop, setScrollTop] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);

  const DAYS_OF_WEEK = getDaysOfWeek('long');
  const DAYS_OF_WEEK_SHORT = getDaysOfWeek('short');
  const TOTAL_HOURS = DAYS_OF_WEEK.length * WORK_DAY_HOURS;

  const visibleColumns = useMemo(() => 
    columnConfig.filter(c => c.alwaysVisible || columnVisibility[c.id as keyof typeof columnVisibility])
  , [columnVisibility, columnConfig]);

  const leftColWidths = useMemo(() => visibleColumns.map(c => columnWidths[c.id]), [visibleColumns, columnWidths]);
  const totalLeftWidth = useMemo(() => leftColWidths.reduce((a, b) => a + b, 0), [leftColWidths]);
  const timelineWidth = TOTAL_HOURS * HOUR_WIDTH;
  const totalGridWidth = totalLeftWidth + timelineWidth;

  const gridRef = useRef<HTMLDivElement>(null);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
    setScrollLeft(e.currentTarget.scrollLeft);
  };

  useEffect(() => {
    if (gridRef.current) {
      setContainerHeight(gridRef.current.clientHeight);
    }
  }, []);

  // Notify parent about interaction state
  useEffect(() => {
    const isInteracting = interaction !== null || isPanning || resizingColumn !== null || draggedTaskId !== null;
    onGanttInteractionChange(isInteracting);
  }, [interaction, isPanning, resizingColumn, onGanttInteractionChange, draggedTaskId]);

  const handleMouseMove = useCallback((event: MouseEvent) => {
    if (!interaction) return;

    const dx = event.clientX - interaction.initialMouseX;
    let updatedTask = { ...interaction.task };

    if (interaction.type === 'drag') {
      const hourDelta = Math.round(dx / HOUR_WIDTH);
      const newTotalStartHour = (interaction.initialDay * WORK_DAY_HOURS) + interaction.initialStartHour + hourDelta;
      const maxTotalStartHour = TOTAL_HOURS - updatedTask.duration;
      const clampedTotalStartHour = Math.max(0, Math.min(newTotalStartHour, maxTotalStartHour));
      updatedTask.day = Math.floor(clampedTotalStartHour / WORK_DAY_HOURS);
      updatedTask.startHour = clampedTotalStartHour % WORK_DAY_HOURS;
    } else if (interaction.type === 'progress') {
        const taskWidthPx = updatedTask.duration * HOUR_WIDTH;
        if (taskWidthPx > 0) {
            const progressDelta = (dx / taskWidthPx) * 100;
            const newProgress = interaction.initialProgress + progressDelta;
            updatedTask.progress = Math.max(0, Math.min(100, Math.round(newProgress)));
        }
    } else if (interaction.type === 'resize-start') {
        const hourDelta = Math.round(dx / HOUR_WIDTH);
        const initialTotalStartHour = (interaction.initialDay * WORK_DAY_HOURS) + interaction.initialStartHour;
        const initialTotalEndHour = initialTotalStartHour + interaction.initialDuration;

        let newTotalStartHour = initialTotalStartHour + hourDelta;

        newTotalStartHour = Math.max(0, Math.min(newTotalStartHour, initialTotalEndHour - 1));

        const newDuration = initialTotalEndHour - newTotalStartHour;

        updatedTask.day = Math.floor(newTotalStartHour / WORK_DAY_HOURS);
        updatedTask.startHour = newTotalStartHour % WORK_DAY_HOURS;
        updatedTask.duration = newDuration;
    } else if (interaction.type === 'resize-end') {
        const hourDelta = Math.round(dx / HOUR_WIDTH);
        const newDuration = interaction.initialDuration + hourDelta;

        const totalStartHour = updatedTask.day * WORK_DAY_HOURS + updatedTask.startHour;
        const maxDuration = TOTAL_HOURS - totalStartHour;

        updatedTask.duration = Math.max(1, Math.min(newDuration, maxDuration));
    }
    setTransientTask(updatedTask);
  }, [interaction, TOTAL_HOURS]);

  const handleMouseUp = useCallback(() => {
    if (interaction && transientTask) {
        onTaskUpdate(transientTask);
    }
    setInteraction(null);
    setTransientTask(null);
    setActiveInteractionTaskId(null);
  }, [interaction, transientTask, onTaskUpdate]);

  const handlePanStart = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.button !== 0 || (e.target as HTMLElement).closest('.group') || (e.target as HTMLElement).closest('.gantt-left-cell') || (e.target as HTMLElement).closest('.header-cell') || (e.target as HTMLElement).closest('svg')) {
        return;
    }

    e.preventDefault();
    setIsPanning(true);
    setPanStart({
        x: e.clientX,
        y: e.clientY,
        scrollLeft: gridRef.current?.scrollLeft || 0,
        scrollTop: gridRef.current?.scrollTop || 0,
    });
  };

  const handleColumnResizeStart = useCallback((event: React.MouseEvent, columnId: string) => {
    event.preventDefault();
    event.stopPropagation();
    setResizingColumn({
        id: columnId,
        startX: event.clientX,
        startWidth: columnWidths[columnId],
    });
  }, [columnWidths]);

  const handleColumnResize = useCallback((event: MouseEvent) => {
    if (!resizingColumn) return;
    const dx = event.clientX - resizingColumn.startX;
    const newWidth = Math.max(60, resizingColumn.startWidth + dx); // Min width 60px
    setColumnWidths(prev => ({...prev, [resizingColumn.id]: newWidth}));
  }, [resizingColumn]);

  const handleColumnResizeEnd = useCallback(() => {
    setResizingColumn(null);
  }, []);

  const handleDragStart = useCallback((e: React.DragEvent, taskId: number) => {
      e.dataTransfer.setData('text/plain', taskId.toString());
      e.dataTransfer.effectAllowed = 'move';
      setDraggedTaskId(taskId);
  }, []);

  const handleDragOver = useCallback((e: React.DragEvent, taskId: number) => {
      e.preventDefault();
      if (taskId !== dragOverTaskId) {
          setDragOverTaskId(taskId);
      }
  }, [dragOverTaskId]);

  const handleDrop = useCallback((e: React.DragEvent, targetTaskId: number) => {
      e.preventDefault();
      if (draggedTaskId !== null && draggedTaskId !== targetTaskId) {
          onTaskReorder(draggedTaskId, targetTaskId);
      }
      setDraggedTaskId(null);
      setDragOverTaskId(null);
  }, [draggedTaskId, onTaskReorder]);

  const handleDragEnd = useCallback(() => {
      setDraggedTaskId(null);
      setDragOverTaskId(null);
  }, []);


  useEffect(() => {
    const ganttElement = gridRef.current;
    const handleWindowMouseMove = (e: MouseEvent) => {
        if (resizingColumn) {
            handleColumnResize(e);
        } else if (isPanning && ganttElement) {
            e.preventDefault();
            const dx = e.clientX - panStart.x;
            const dy = e.clientY - panStart.y;
            ganttElement.scrollLeft = panStart.scrollLeft - dx;
            ganttElement.scrollTop = panStart.scrollTop - dy;
        } else if (interaction) {
            handleMouseMove(e);
        }
    };
    const handleWindowMouseUp = () => {
        setIsPanning(false);
        if (interaction) {
            handleMouseUp();
        }
        if (resizingColumn) {
            handleColumnResizeEnd();
        }
    };
    window.addEventListener('mousemove', handleWindowMouseMove);
    window.addEventListener('mouseup', handleWindowMouseUp);
    return () => {
        window.removeEventListener('mousemove', handleWindowMouseMove);
        window.removeEventListener('mouseup', handleWindowMouseUp);
    };
  }, [isPanning, panStart, interaction, handleMouseMove, handleMouseUp, resizingColumn, handleColumnResize, handleColumnResizeEnd]);

  useEffect(() => {
      const ganttElement = gridRef.current;
      if (!ganttElement) return;

      if (resizingColumn) {
          document.body.style.cursor = 'col-resize';
      } else if (isPanning) {
          document.body.style.cursor = 'grabbing';
          ganttElement.style.cursor = 'grabbing';
      } else if (interaction) {
          ganttElement.style.cursor = 'default';
          if (interaction.type === 'drag') document.body.style.cursor = 'move';
          else if (interaction.type === 'progress') document.body.style.cursor = 'col-resize';
          else if (interaction.type === 'resize-start') document.body.style.cursor = 'w-resize';
          else if (interaction.type === 'resize-end') document.body.style.cursor = 'e-resize';
      } else {
          document.body.style.cursor = 'default';
          ganttElement.style.cursor = 'default';
      }

      return () => { document.body.style.cursor = 'default'; };
  }, [isPanning, interaction, resizingColumn]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (statusPopup.isOpen && statusPopupRef.current && !statusPopupRef.current.contains(event.target as Node)) {
        setStatusPopup({ isOpen: false, task: null, position: { top: 0, left: 0 } });
      }
      if (contextMenu.isOpen && contextMenuRef.current && !contextMenuRef.current.contains(event.target as Node)) {
          setContextMenu(prev => ({ ...prev, isOpen: false }));
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [statusPopup.isOpen, contextMenu.isOpen]);

  const handleInteractionStart = (
    type: 'drag' | 'progress' | 'resize-start' | 'resize-end',
    event: React.MouseEvent,
    task: Task
  ) => {
    if (task.status === TaskStatus.Completed || task.status === TaskStatus.QualityOK || event.button !== 0) return;
    event.stopPropagation();
    setActiveInteractionTaskId(task.id);
    setInteraction({ 
        type, 
        task, 
        initialMouseX: event.clientX, 
        initialStartHour: task.startHour, 
        initialDay: task.day, 
        initialProgress: task.progress,
        initialDuration: task.duration
    });
    setTransientTask(task);
  };

  const handleStatusClick = (event: React.MouseEvent, task: Task) => {
    if (task.status === TaskStatus.QualityOK) return;
    event.stopPropagation();
    const rect = event.currentTarget.getBoundingClientRect();
    setStatusPopup({
      isOpen: true,
      task,
      position: { top: rect.bottom + 4, left: rect.left },
    });
  };

  const handleStatusChange = (newStatus: TaskStatus) => {
    if (statusPopup.task) {
      const updatedTask = { ...statusPopup.task, status: newStatus };
      if (newStatus === TaskStatus.Completed) {
        updatedTask.progress = 100;
      } else if (statusPopup.task.status === TaskStatus.Completed) {
        updatedTask.progress = 90;
      }
      onTaskUpdate(updatedTask);
    }
    setStatusPopup({ isOpen: false, task: null, position: { top: 0, left: 0 } });
  };

  const handleQualityCheck = (task: Task, isChecked: boolean) => {
      if (isChecked && task.status === TaskStatus.Completed) {
          onTaskUpdate({ ...task, status: TaskStatus.QualityOK });
      }
  };

  const handleContextMenuAction = (status: TaskStatus) => {
      if (contextMenu.task) {
          const updatedTask = { ...contextMenu.task, status };
          if (status === TaskStatus.Completed) {
              updatedTask.progress = 100;
          } else if (contextMenu.task.status === TaskStatus.Completed) {
              updatedTask.progress = 90; // Revert to in-progress state approximate
          }
          onTaskUpdate(updatedTask);
      }
      setContextMenu(prev => ({ ...prev, isOpen: false }));
  };

  const handleTaskContextMenu = (event: React.MouseEvent, task: Task) => {
      setContextMenu({
          isOpen: true,
          x: event.clientX,
          y: event.clientY,
          task
      });
  };

  const isTaskOverdue = (task: Task) => {
    const endTotalHour = (task.day * WORK_DAY_HOURS) + task.startHour + task.duration;
    const dueTotalHour = (task.dueDay * WORK_DAY_HOURS) + task.dueHour + 1; // Due by end of hour
    return endTotalHour > dueTotalHour;
  };

  const getFormattedTime = (hourIndex: number) => {
      const hour = hourIndex + 8; // 8 AM is our base
      return `${hour % 12 === 0 ? 12 : hour % 12}:00 ${hour >= 12 && hour < 24 ? 'PM' : 'AM'}`;
  };

  const renderCellContent = (task: Task, columnId: string) => {
    const isOverdueValue = isTaskOverdue(task);
    switch (columnId) {
        case 'task':
            return (
                <>
                    <div className={`w-1.5 h-full rounded-full mr-3 flex-shrink-0 ${task.isCritical ? 'bg-orange-400' : (isOverdueValue && task.status !== TaskStatus.Completed && task.status !== TaskStatus.QualityOK ? 'bg-red-500' : 'bg-transparent')}`}></div>
                    <span className="font-medium text-slate-100 truncate">{task.name}</span>
                </>
            );
        case 'orderId':
            return <span className="text-slate-400 font-mono text-sm">{task.orderId}</span>;
        case 'quality':
            const isQualityCheckable = task.status === TaskStatus.Completed;
            const isQualityOK = task.status === TaskStatus.QualityOK;
            return (
                <div className="w-full flex justify-center">
                    <input
                        type="checkbox"
                        checked={isQualityOK}
                        disabled={!isQualityCheckable && !isQualityOK}
                        onChange={(e) => handleQualityCheck(task, e.target.checked)}
                        onClick={(e) => e.stopPropagation()} // Prevent row selection
                        className="h-5 w-5 rounded bg-slate-600 border-slate-500 text-purple-500 focus:ring-purple-500 disabled:opacity-50 disabled:cursor-not-allowed"
                        title={isQualityCheckable ? t('gantt.quality.checkableTooltip') : isQualityOK ? t('gantt.quality.checkedTooltip') : t('gantt.quality.disabledTooltip')}
                    />
                </div>
            );
        case 'realisation':
            const realisedHours = (task.duration * task.progress) / 100;
            const isTrackingLate = isOverdueValue && task.progress < 100;
            const textColor = isTrackingLate ? 'text-red-400 font-bold' : 'text-green-400';
            return (
              <span className={`font-medium ${textColor}`}>
                {t('gantt.realisation.hours', realisedHours.toFixed(1))}
              </span>
            );
        case 'assignedTo':
            return (
                <button
                    onDoubleClick={(e) => {
                        e.stopPropagation();
                        onOperatorSelect(task.assignedTo);
                    }}
                    className="text-slate-300 truncate text-left w-full h-full hover:text-cyan-400 font-medium transition-colors"
                >
                    {task.assignedTo}
                </button>
            );
        case 'status':
            const statusColor = TASK_STATUS_COLORS[task.status];
            const isQualityOKStatus = task.status === TaskStatus.QualityOK;
            return (
                <button
                    onClick={(e) => handleStatusClick(e, task)}
                    disabled={isQualityOKStatus}
                    className={`w-full text-center px-2.5 py-1 text-xs font-bold rounded-full whitespace-nowrap ${statusColor.background} ${statusColor.text} ${!isQualityOKStatus && 'transition-all hover:ring-2 hover:ring-offset-2 hover:ring-offset-slate-800 hover:ring-cyan-400'} disabled:cursor-default disabled:hover:ring-0`}
                >
                    {getTaskStatusName(task.status)}
                </button>
            );
        case 'progress':
            let progressColor = 'bg-green-500';
            if (task.status === TaskStatus.QualityOK) {
                progressColor = 'bg-purple-500';
            } else if (task.progress === 100) {
                progressColor = 'bg-emerald-500';
            } else if (isOverdueValue) {
                progressColor = 'bg-red-500';
            }

            return (
                <div className="w-full flex items-center gap-2">
                    <div className="w-full bg-slate-600 rounded-full h-2">
                        <div 
                            className={`${progressColor} h-2 rounded-full transition-colors`} 
                            style={{ width: `${task.progress}%` }}
                        ></div>
                    </div>
                    <span className="text-xs font-mono text-slate-400 w-8 text-right">{task.progress}%</span>
                </div>
            );
        case 'dueBy':
            const dueDateString = `${DAYS_OF_WEEK_SHORT[task.dueDay]}`;
            const dueTime = getFormattedTime(task.dueHour + 1);
            return <span className="text-slate-300 text-sm font-medium">{`${dueDateString}, ${dueTime}`}</span>;
        case 'duration':
            return <span className="text-slate-300 font-medium">{t('gantt.duration.hours', task.duration)}</span>;
        default:
            return null;
    }
  };

  // 1. Stable map of all tasks with their indices. Re-computes only when tasks list changes (order/add/remove).
  const taskMapWithIndex = useMemo(() => new Map(tasks.map((t, i) => [t.id, { task: t, index: i }])), [tasks]);

  // VIRTUALIZATION LOGIC
  const startIndex = Math.max(0, Math.floor(scrollTop / TASK_ROW_HEIGHT) - OVERSCAN_COUNT);
  const visibleItemCount = containerHeight ? Math.ceil(containerHeight / TASK_ROW_HEIGHT) : 0;
  const endIndex = Math.min(tasks.length, startIndex + visibleItemCount + OVERSCAN_COUNT * 2);

  const visibleItems = useMemo(() => {
    const items = [];
    for (let i = startIndex; i < endIndex; i++) {
        let task = tasks[i];
        if (transientTask && task.id === transientTask.id) {
            task = transientTask;
        }
        items.push({ task, index: i });
    }
    return items;
  }, [startIndex, endIndex, tasks, transientTask]);

  return (
    <div className="bg-slate-800 text-white rounded-2xl shadow-2xl h-full flex flex-col overflow-hidden">
        <GanttFilters masterTasks={masterTasks} allOperators={allOperators} filters={filters} onFilterChange={onFilterChange} onClearFilters={onClearFilters} />
        <div 
            ref={gridRef} 
            onScroll={handleScroll}
            className="overflow-auto flex-grow w-full select-none relative"
        >
            {/* STICKY HEADER */}
            <div 
                className="sticky top-0 z-20 flex"
                style={{ width: totalGridWidth, height: HEADER_HEIGHT }}
            >
                {/* Left Columns Header */}
                <div className="flex flex-shrink-0 bg-sky-900">
                    {visibleColumns.map((col) => (
                        <div key={col.id} title={col.label} className={`group relative font-semibold text-slate-100 text-sm p-3 flex flex-col items-center justify-center text-center border-b-2 border-r border-sky-800 header-cell`} style={{width: columnWidths[col.id], height: HEADER_HEIGHT}}>
                            <div className="flex items-center gap-2">
                                {col.icon}
                            </div>
                            <span className="transition-colors group-hover:text-cyan-400 mt-1">{col.label}</span>
                            <div
                                onMouseDown={(e) => handleColumnResizeStart(e, col.id)}
                                className="absolute top-0 right-0 h-full w-2 cursor-col-resize opacity-0 group-hover:opacity-100 hover:bg-cyan-500/30 transition-all"
                                title={t('gantt.resizeColumn', col.label)}
                            />
                        </div>
                    ))}
                </div>
                {/* Timeline Header */}
                <div className="flex-1 flex flex-col bg-sky-900" style={{height: HEADER_HEIGHT}}>
                    <div className="flex flex-1">
                    {DAYS_OF_WEEK.map((day) => (
                        <div key={day} className="flex items-center justify-center text-slate-100 font-bold text-base border-b-2 border-sky-800/80" style={{width: WORK_DAY_HOURS * HOUR_WIDTH}}>{day}</div>
                    ))}
                    </div>
                    <div className="flex flex-1">
                    {Array.from({length: TOTAL_HOURS}).map((_, hourIndex) => (
                        <div key={`h-${hourIndex}`} className="flex items-center justify-center text-slate-300 text-xs border-b border-r border-sky-800/80" style={{width: HOUR_WIDTH}}>{WORK_HOURS[hourIndex % WORK_DAY_HOURS]}</div>
                    ))}
                    </div>
                </div>
            </div>

            {/* VIRTUALIZED BODY */}
            <div style={{ height: tasks.length * TASK_ROW_HEIGHT, width: totalGridWidth, position: 'relative' }} onDragOver={(e) => e.preventDefault()}>

                {/* Dependency Lines */}
                <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ top: HEADER_HEIGHT }}>
                    <defs>
                        <marker id="arrowhead" markerWidth="6" markerHeight="4" refX="5" refY="2" orient="auto">
                            <polygon points="0 0, 6 2, 0 4" fill="#a78bfa" />
                        </marker>
                    </defs>
                    {visibleItems.map(({ task: dependentTask, index: dependentIndex }) =>
                        (dependentTask.dependencies || []).map(prereqId => {
                            const prereqInfo = taskMapWithIndex.get(prereqId);

                            // Prerequisite is not visible (filtered out), so don't draw the line.
                            if (!prereqInfo) {
                                return null;
                            }

                            let prereqTask = prereqInfo.task;
                            // If the prerequisite is active transient task, use that position
                            if (transientTask && prereqTask.id === transientTask.id) {
                                prereqTask = transientTask;
                            }

                            const startY = prereqInfo.index * TASK_ROW_HEIGHT + TASK_ROW_HEIGHT / 2 - scrollTop;
                            const endY = dependentIndex * TASK_ROW_HEIGHT + TASK_ROW_HEIGHT / 2 - scrollTop;

                            // Optimization: Only render if both tasks are somewhat in view
                            if ((startY < -50 && endY < -50) || (startY > containerHeight + 50 && endY > containerHeight + 50)) {
                                return null;
                            }

                            const startX = totalLeftWidth + (prereqTask.day * WORK_DAY_HOURS + prereqTask.startHour + prereqTask.duration) * HOUR_WIDTH;
                            const endX = totalLeftWidth + (dependentTask.day * WORK_DAY_HOURS + dependentTask.startHour) * HOUR_WIDTH;

                            const c1X = startX + HOUR_WIDTH * 1.5;
                            const c1Y = startY;
                            const c2X = endX - HOUR_WIDTH * 1.5;
                            const c2Y = endY;

                            return (
                                <path
                                    key={`${prereqId}-${dependentTask.id}`}
                                    d={`M ${startX} ${startY} C ${c1X} ${c1Y}, ${c2X} ${c2Y}, ${endX - 8} ${endY}`}
                                    stroke="#a78bfa"
                                    strokeWidth="2"
                                    fill="none"
                                    strokeOpacity="0.8"
                                    markerEnd="url(#arrowhead)"
                                />
                            );
                        })
                    )}
                </svg>

                {visibleItems.map(({ task, index }) => {
                    const isBeingDragged = draggedTaskId === task.id;
                    const isDragTarget = dragOverTaskId === task.id;
                    return (
                        <div
                            key={task.id}
                            draggable
                            onDragStart={(e) => handleDragStart(e, task.id)}
                            onDragOver={(e) => handleDragOver(e, task.id)}
                            onDrop={(e) => handleDrop(e, task.id)}
                            onDragEnd={handleDragEnd}
                            onDragLeave={() => setDragOverTaskId(null)}
                            style={{
                                position: 'absolute',
                                top: index * TASK_ROW_HEIGHT,
                                left: 0,
                                height: TASK_ROW_HEIGHT,
                                width: totalGridWidth,
                            }}
                            className={`flex items-stretch cursor-grab ${isBeingDragged ? 'opacity-50' : ''} ${isDragTarget ? 'bg-cyan-500/20' : ''}`}
                        >
                            {/* Left Cells */}
                            <div 
                                className={`flex flex-shrink-0 ${
                                    task.id === selectedTaskId || task.id === activeInteractionTaskId ? 'bg-slate-700' : (index % 2 !== 0 ? 'bg-slate-900' : 'bg-slate-800')
                                } transition-colors duration-200`}
                                style={{ width: totalLeftWidth }}
                            >
                                {visibleColumns.map(col => (
                                    <div
                                        key={col.id}
                                        onDoubleClick={() => onTaskSelect(task)}
                                        className="flex items-center p-2 border-b border-r border-slate-700/50 gantt-left-cell"
                                        style={{width: columnWidths[col.id]}}
                                    >
                                        {renderCellContent(task, col.id)}
                                    </div>
                                ))}
                            </div>

                            {/* Right Timeline Pane */}
                            <div
                                style={{ 
                                    width: timelineWidth, 
                                    height: TASK_ROW_HEIGHT,
                                    backgroundImage: `linear-gradient(to right, transparent 39px, rgba(51, 65, 85, 0.3) 39px, rgba(51, 65, 85, 0.3) 40px)`,
                                    backgroundSize: `${HOUR_WIDTH}px 100%`
                                }}
                                className={`relative border-b border-slate-700/50 ${
                                    task.id === selectedTaskId || task.id === activeInteractionTaskId ? 'bg-slate-700' : (index % 2 !== 0 ? 'bg-slate-900' : 'bg-slate-800')
                                } transition-colors duration-200`}
                            >
                                <TaskBlock
                                    task={task}
                                    onInteractionStart={handleInteractionStart}
                                    onDoubleClick={onTaskSelect}
                                    onContextMenu={handleTaskContextMenu}
                                    isSelected={task.id === selectedTaskId || task.id === activeInteractionTaskId}
                                    isOverdue={isTaskOverdue(task)}
                                    left={ (task.day * WORK_DAY_HOURS + task.startHour) * HOUR_WIDTH}
                                    width={task.duration * HOUR_WIDTH}
                                />
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>

      {/* Status Popup (Left Column) */}
      {statusPopup.isOpen && statusPopup.task && (
        <div
          ref={statusPopupRef}
          className="fixed z-50 bg-slate-900/80 backdrop-blur-sm border border-slate-600 rounded-lg shadow-2xl p-2"
          style={{ top: statusPopup.position.top, left: statusPopup.position.left }}
        >
          <div className="flex flex-col gap-1 w-36">
            {Object.values(TaskStatus).filter(s => s !== TaskStatus.QualityOK).map(status => (
              <button
                key={status}
                onClick={() => handleStatusChange(status)}
                className={`px-3 py-1.5 text-sm text-left rounded-md w-full ${TASK_STATUS_COLORS[status].text} ${TASK_STATUS_COLORS[status].background} hover:brightness-125 transition-all disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:brightness-100`}
                disabled={status === statusPopup.task?.status}
              >
                {getTaskStatusName(status)}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Context Menu (Task Blocks) */}
      {contextMenu.isOpen && contextMenu.task && (
          <div
              ref={contextMenuRef}
              className="fixed z-50 bg-slate-900/90 backdrop-blur-md border border-slate-700 rounded-xl shadow-2xl p-1.5 min-w-[160px] animate-fade-in-up"
              style={{ top: contextMenu.y, left: contextMenu.x }}
          >
              <div className="px-3 py-2 text-xs font-bold text-slate-400 uppercase tracking-wider border-b border-slate-700 mb-1">
                  {t('columns.status')}
              </div>
              <div className="flex flex-col gap-1">
                  {Object.values(TaskStatus).filter(s => s !== TaskStatus.QualityOK).map(status => (
                      <button
                          key={status}
                          onClick={() => handleContextMenuAction(status)}
                          className={`px-3 py-2 text-sm text-left rounded-lg w-full flex items-center gap-2 transition-all ${
                              contextMenu.task?.status === status 
                                  ? 'bg-slate-700 text-white' 
                                  : 'text-slate-300 hover:bg-slate-800 hover:text-white'
                          }`}
                      >
                          <div className={`w-2 h-2 rounded-full ${TASK_STATUS_COLORS[status].background.replace('bg-', 'bg-')}`}></div>
                          {getTaskStatusName(status)}
                      </button>
                  ))}
              </div>
          </div>
      )}
    </div>
  );
};

