interface UserLogPageProps {
  allOperators: string[];
  allTasks: Task[];
  masterTasks: MasterTask[];
  onUpdateMasterTasks: (tasks: MasterTask[]) => void;
  proficiencyOverrides: ProficiencyOverrides;
