const UserLogPage: React.FC<UserLogPageProps> = ({ allOperators, allTasks, masterTasks, onUpdateMasterTasks, proficiencyOverrides, onUpdateOverrides, rankSettings, onUpdateRankSettings }) => {
  const { t } = useLocalization();

  const [programSearch, setProgramSearch] = useState('');
  const [operatorSearch, setOperatorSearch] = useState('');
  const [selectedPrograms, setSelectedPrograms] = useState<string[]>([]);
  const [selectedOperators, setSelectedOperators] = useState<string[]>([]);

  const [pendingOverrides, setPendingOverrides] = useState<ProficiencyOverrides>(proficiencyOverrides);
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
  const [isAddTaskModalOpen, setIsAddTaskModalOpen] = useState(false);

  useEffect(() => {
    setPendingOverrides(proficiencyOverrides);
  }, [proficiencyOverrides]);

  const areChangesUnsaved = useMemo(() => !deepEqual(proficiencyOverrides, pendingOverrides), [proficiencyOverrides, pendingOverrides]);

  const metrics = useMemo(() => {
        const calculatedCounts: { [key: string]: number } = {};
        allTasks.forEach(task => {
            if (task.assignedTo && (task.status === TaskStatus.Completed || task.status === TaskStatus.QualityOK)) {
                const key = `${task.assignedTo}::${task.name}`;
                calculatedCounts[key] = (calculatedCounts[key] || 0) + 1;
            }
        });

        const getProficiencyCount = (operator: string, taskName: string): number => {
            return proficiencyOverrides[operator]?.[taskName] ?? calculatedCounts[`${operator}::${taskName}`] ?? 0;
        };

        let totalScore = 0;
        const totalPossibleEntries = allOperators.length * masterTasks.length;
        allOperators.forEach(op => {
            masterTasks.forEach(mTask => {
                const count = getProficiencyCount(op, mTask.name);
                const rank = getRank(count, rankSettings);
                totalScore += rankToScore[rank];
            });
        });
        const teamVersatilityScore = totalPossibleEntries > 0 ? ((totalScore / (totalPossibleEntries * 5)) * 100).toFixed(1) : '0.0';

        const totalCompletions = Object.values(calculatedCounts).reduce((sum, count) => sum + count, 0);

        const masterOperators = new Set<string>();
        allOperators.forEach(op => {
            masterTasks.forEach(mTask => {
                const count = getProficiencyCount(op, mTask.name);
                if (getRank(count, rankSettings) === Rank.Master) {
                    masterOperators.add(op);
                }
            });
        });
        const masterRankCount = masterOperators.size;

        let mostVersatile = { name: t('na'), count: 0 };
        allOperators.forEach(op => {
            let proficientTaskCount = 0;
            masterTasks.forEach(mTask => {
                if (getProficiencyCount(op, mTask.name) > 0) {
                    proficientTaskCount++;
                }
            });
            if (proficientTaskCount > mostVersatile.count) {
                mostVersatile = { name: op, count: proficientTaskCount };
            }
        });

        return { teamVersatilityScore, totalCompletions, masterRankCount, mostVersatileOperator: mostVersatile.name };
    }, [allTasks, allOperators, masterTasks, proficiencyOverrides, rankSettings, rankToScore, t]);

  const handleSave = () => {
    onUpdateOverrides(pendingOverrides);
  };

  const handleDiscard = () => {
    setPendingOverrides(proficiencyOverrides);
  };

  const handleAddTask = (newTask: MasterTask) => {
      onUpdateMasterTasks([...masterTasks, newTask]);
  };

  const uniquePrograms = useMemo(() => Array.from(new Set(masterTasks.map(mt => mt.program))), [masterTasks]);

  const handleProgramFilterChange = (program: string) => {
    setSelectedPrograms(prev => 
        prev.includes(program) ? prev.filter(p => p !== program) : [...prev, program]
    );
  };

  const handleOperatorFilterChange = (operator: string) => {
      setSelectedOperators(prev => 
          prev.includes(operator) ? prev.filter(o => o !== operator) : [...prev, operator]
      );
  };

  const clearFilters = () => {
      setProgramSearch('');
      setOperatorSearch('');
      setSelectedPrograms([]);
      setSelectedOperators([]);
  };

  const hasActiveFilters = selectedPrograms.length > 0 || selectedOperators.length > 0;

  const filteredMasterTasks = useMemo(() => {
      if (selectedPrograms.length === 0) return masterTasks;
      return masterTasks.filter(task => selectedPrograms.includes(task.program));
  }, [masterTasks, selectedPrograms]);

  const filteredOperators = useMemo(() => {
      if (selectedOperators.length === 0) return allOperators;
      return allOperators.filter(op => selectedOperators.includes(op));
  }, [allOperators, selectedOperators]);

  const searchedPrograms = useMemo(() =>
      uniquePrograms.filter(p => p.toLowerCase().includes(programSearch.toLowerCase()))
  , [uniquePrograms, programSearch]);

  const searchedOperators = useMemo(() =>
      allOperators.filter(op => op.toLowerCase().includes(operatorSearch.toLowerCase()))
  , [allOperators, operatorSearch]);

  return (
    <div className="w-full h-full bg-slate-900 text-slate-100 flex flex-col p-6 overflow-hidden">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6 flex-shrink-0">
        <MetricCard icon={<TeamIcon />} title={t('userlog.metrics.teamVersatility')} value={`${metrics.teamVersatilityScore}%`} />
        <MetricCard icon={<CheckBadgeIcon />} title={t('userlog.metrics.totalCompletions')} value={metrics.totalCompletions} />
        <MetricCard icon={<StarIcon />} title={t('userlog.metrics.masterOperators')} value={metrics.masterRankCount} />
        <MetricCard icon={<CrownIcon />} title={t('userlog.metrics.mostVersatile')} value={metrics.mostVersatileOperator} />
      </div>

      <header className="flex items-center justify-between pb-4 border-b border-slate-700 mb-4 flex-shrink-0 flex-wrap gap-4">
        <div>
          <h2 className="text-xl font-bold text-white mb-1">{t('pageTitle.userlog')}</h2>
          <p className="text-sm text-slate-400"><span className="italic">{t('userlog.editInstruction')}</span></p>
        </div>
        <div className="flex items-center gap-4">
          {areChangesUnsaved && (
                <div className="flex items-center gap-3 animate-pulse bg-yellow-900/20 px-3 py-1.5 rounded-lg border border-yellow-700/50">
                    <span className="text-sm font-semibold text-yellow-400">{t('userlog.unsavedChanges')}</span>
                    <button onClick={handleDiscard} className="px-3 py-1.5 text-sm font-semibold rounded-lg bg-slate-700 hover:bg-slate-600 text-white transition-colors">{t('actions.discard')}</button>
                    <button onClick={handleSave} className="px-3 py-1.5 text-sm font-semibold rounded-lg bg-green-600 hover:bg-green-500 text-white transition-colors shadow-lg shadow-green-900/20">{t('actions.saveChanges')}</button>
                </div>
            )}
            <button onClick={() => setIsAddTaskModalOpen(true)} className="flex items-center gap-2 px-3 py-2 text-sm font-semibold rounded-lg bg-slate-700 hover:bg-slate-600 text-white transition-colors border border-slate-600">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clipRule="evenodd" /></svg>
                {t('userlog.actions.addTask')}
            </button>
            <button onClick={() => setIsSettingsModalOpen(true)} className="flex items-center gap-2 px-3 py-2 text-sm font-semibold rounded-lg bg-slate-700 hover:bg-slate-600 text-white transition-colors border border-slate-600">
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M11.49 3.17c-.38-1.56-2.6-1.56-2.98 0a1.532 1.532 0 01-2.286.948c-1.372-.836-2.942.734-2.106 2.106.54.886.061 2.042-.947 2.287-1.561.379-1.561 2.6 0 2.978a1.532 1.532 0 01.947 2.287c-.836 1.372.734 2.942 2.106 2.106a1.532 1.532 0 012.287.947c.379 1.561 2.6 1.561 2.978 0a1.532 1.532 0 012.287-.947c1.372.836 2.942-.734 2.106-2.106a1.532 1.532 0 01-.947-2.287c1.561-.379 1.561-2.6 0-2.978a1.532 1.532 0 01-.947-2.287c.836-1.372-.734-2.942-2.106-2.106a1.532 1.532 0 01-2.287-.947zM10 13a3 3 0 100-6 3 3 0 000 6z" clipRule="evenodd" /></svg>
                {t('userlog.actions.settings')}
            </button>
        </div>
      </header>

      <div className="flex-grow flex gap-6 overflow-hidden">
        {/* Filter Panel */}
        <aside className="w-64 flex-shrink-0 bg-slate-800 rounded-xl p-4 flex flex-col gap-6 border border-slate-700 shadow-md">
          <div className="flex justify-between items-center">
              <h3 className="text-sm font-bold text-slate-200 uppercase tracking-wider">{t('userlog.filters.title')}</h3>
              { hasActiveFilters && (
                  <button onClick={clearFilters} className="text-xs font-semibold text-red-400 hover:text-red-300 transition-colors">
                      {t('actions.clearAll')}
                  </button>
              )}
          </div>

          {/* Program Filter */}
          <div className="flex-1 flex flex-col min-h-0">
              <h4 className="font-semibold text-slate-400 text-xs mb-2 px-1 uppercase">{t('userlog.filters.byProgram')}</h4>
              <div className="relative mb-2">
                  <input
                      type="search"
                      placeholder={t('userlog.filters.searchPrograms')}
                      value={programSearch}
                      onChange={(e) => setProgramSearch(e.target.value)}
                      className="w-full bg-slate-900/80 border border-slate-700 rounded-lg pl-9 pr-3 py-2 text-sm text-white placeholder-slate-500 focus:outline-none focus:ring-1 focus:ring-cyan-500 focus:border-cyan-500"
                  />
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z" clipRule="evenodd" />
                  </svg>
              </div>
              <div className="space-y-0.5 overflow-y-auto pr-1 custom-scrollbar">
                  {searchedPrograms.map(prog => (
                      <FilterCheckbox
                          key={prog}
                          label={prog}
                          isChecked={selectedPrograms.includes(prog)}
                          onChange={() => handleProgramFilterChange(prog)}
                      />
                  ))}
              </div>
          </div>

          {/* Operator Filter */}
          <div className="flex-1 flex flex-col min-h-0 border-t border-slate-700 pt-4">
              <h4 className="font-semibold text-slate-400 text-xs mb-2 px-1 uppercase">{t('userlog.filters.byOperator')}</h4>
              <div className="relative mb-2">
                  <input
                      type="search"
                      placeholder={t('userlog.filters.searchOperators')}
                      value={operatorSearch}
                      onChange={(e) => setOperatorSearch(e.target.value)}
                      className="w-full bg-slate-900/80 border border-slate-700 rounded-lg pl-9 pr-3 py-2 text-sm text-white placeholder-slate-500 focus:outline-none focus:ring-1 focus:ring-cyan-500 focus:border-cyan-500"
                  />
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z" clipRule="evenodd" />
                  </svg>
              </div>
              <div className="space-y-0.5 overflow-y-auto pr-1 custom-scrollbar">
                  {searchedOperators.map(op => (
                      <FilterCheckbox
                          key={op}
                          label={op}
                          isChecked={selectedOperators.includes(op)}
                          onChange={() => handleOperatorFilterChange(op)}
                      />
                  ))}
              </div>
          </div>
        </aside>

        <main className="flex-grow flex flex-col overflow-hidden min-w-0">
          <VersatilityGrid 
              allOperators={filteredOperators} 
              allTasks={allTasks} 
              masterTasks={filteredMasterTasks}
              proficiencyOverrides={pendingOverrides}
              onUpdateOverrides={setPendingOverrides}
              rankSettings={rankSettings}
          />
        </main>
      </div>
      {isAddTaskModalOpen && <AddTaskModal onClose={() => setIsAddTaskModalOpen(false)} onAddTask={handleAddTask} existingPrograms={uniquePrograms} masterTasks={masterTasks} />}
      {isSettingsModalOpen && <SettingsModal onClose={() => setIsSettingsModalOpen(false)} onSave={onUpdateRankSettings} currentSettings={rankSettings} />}
    </div>
  );
};

export default UserLogPage;
